/**
 * Сколько раз запись повторяется, когда её перебивает чужая сессия. Потолок
 * нужен: без него две встречные записи, идущие сплошным потоком, крутили бы
 * друг друга бесконечно. Четырёх хватает — окно гонки это доли секунды, и
 * подряд проиграть четыре раза значит, что писать сейчас просто не время.
 */
const WRITE_ATTEMPTS = 4;

/**
 * Потолок поиска — отдельный и много выше потолка сплошного прохода.
 *
 * Проход оплачивается в каждом разборе фразы, поиск — только когда его позвали,
 * и наружу он отдаёт найденные строки, а не тексты файлов: цена вопроса — один
 * батч из хранилища, а не окно модели. При этом именно поиск обещает «искали
 * везде», и обещание должно быть правдой хотя бы на нынешнем задачнике (около
 * ста файлов вместе с отчётами).
 */
const SEARCH_MAX = 200;

function createTasksTools({
  api, curatorJwt, clientId, nowMs = Date.now(), ToolError, writeContext = null,
  // Хранилище вложений подставляется тестами целиком: до сети они не доходят,
  // и проверочный мусор в боевой репозиторий не уезжает.
  assetsClient = null, env = process.env,
}) {
  let indexPromise = null;
  let statePromise = null;

  /**
   * Токен читается лениво и только здесь. В аргументы инструмента он не
   * входит, наружу не возвращается и в текст ошибки не попадает: наличие
   * секрета видно по факту «настроено / не настроено», а не по значению.
   */
  function requireAssets() {
    if (assetsClient) return assetsClient;
    const token = env && env.TASKS_ASSETS_TOKEN;
    if (!token) {
      throw new ToolError(
        'attachments_not_configured',
        'Хранилище вложений не подключено: доступ на запись не задан. Скажи ему — он положит его в секреты. Пока этого нет, файл приложить нельзя, и делать вид, что приложил, тоже нельзя.',
      );
    }
    return assets.createAssetsClient({
      token,
      repo: (env && env.TASKS_ASSETS_REPO) || assets.DEFAULT_REPO,
      branch: (env && env.TASKS_ASSETS_BRANCH) || assets.DEFAULT_BRANCH,
    });
  }

  function requireClient() {
    if (!clientId) {
      throw new ToolError(
        'tasks_not_configured',
        'Задачник не подключён: не задан клиент, под которым он живёт (HEYS_TASKS_CLIENT_ID).',
      );
    }
  }

  async function loadIndex() {
    requireClient();
    if (!indexPromise) {
      indexPromise = (async () => {
        const { data, error } = await api.getKVByCurator(curatorJwt, clientId, tasks.INDEX_KEY);
        if (error) throw new ToolError('upstream_error', `Не удалось прочитать индекс задачника: ${error.message}`);
        return tasks.ensureIndex(data);
      })();
      indexPromise.catch(() => { indexPromise = null; });
    }
    return indexPromise;
  }

  async function readFile(path) {
    requireClient();
    const normalized = tasks.normalizePath(path);
    if (!normalized) throw new ToolError('invalid_path', `Путь «${path}» не похож на файл задачника.`);
    const key = tasks.keyForPath(normalized);
    const { data, error } = await api.getKVByCurator(curatorJwt, clientId, key);
    if (error) throw new ToolError('upstream_error', `Не удалось прочитать ${normalized}: ${error.message}`);
    return tasks.ensureFile(data, normalized);
  }

  /**
   * Чтение пачкой по индексу. Батч ограничен: задачник целиком — это десятки
   * килобайт текста, и тащить их в каждый поиск незачем. Приоритет отдаётся
   * файлам, где ответ вероятнее: проекты, журнал, дни.
   *
   * Разовые отчёты в docs/ из сплошного прохода выкинуты: по объёму это больше
   * половины задачника, а отвечают они ровно на один вопрос — тот, ради
   * которого их однажды написали. Поднять их за потолок нельзя (тогда каждый
   * разбор фразы тащит ≈97 тысяч токенов чужих аудитов), оставить в проходе
   * последними — тоже: они и вытеснили рабочую память. Отдельным вызовом,
   * прямым поиском и через tasks_read они по-прежнему доступны целиком, для
   * этого есть `reports: true`.
   *
   * Что не поместилось, возвращается списком. Раньше отсечение было немым, и
   * поверх него стояло обещание «искали везде»: непрочитанный файл и
   * отсутствующий ответ выглядели одинаково, а разница между ними — это разница
   * между «нет» и «не смотрел».
   */
  async function readAllWithMeta({ paths = null, max = 60, reports = false } = {}) {
    const index = await loadIndex();
    const asked = paths && paths.length;
    const known = (asked ? paths : Object.keys(index.files))
      // Названный поимённо файл читается всегда: отказать в том, что попросили,
      // хуже, чем прочитать лишнее.
      .filter((path) => asked || reports || !tasks.isOneOffReport(path));
    if (!known.length) return { files: [], skipped: [], total: 0 };
    // Порядок — по смыслу, а не по алфавиту: иначе растущая папка дней
    // вытеснит из чтения сами задачи, и поиск начнёт молча «не находить».
    // Потолок на датированную папку названный поимённо список не режет: лишнее
    // уходит в хвост, а не выбрасывается, и при max по длине списка (календарь
    // на два месяца, все проекты) возвращается целиком.
    const selected = tasks.selectPaths(known, { today: today(), max });
    const taken = new Set(selected);
    const keys = selected.map((path) => tasks.keyForPath(path)).filter(Boolean);
    const { data, error } = await api.getKVManyByCurator(curatorJwt, clientId, keys);
    if (error) throw new ToolError('upstream_error', `Не удалось прочитать задачник: ${error.message}`);
    const byKey = data || {};
    return {
      files: selected
        .map((path) => tasks.ensureFile(byKey[tasks.keyForPath(path)], path))
        .filter((file) => file.text),
      skipped: known.filter((path) => !taken.has(path)),
      total: known.length,
    };
  }

  async function readAll(options = {}) {
    return (await readAllWithMeta(options)).files;
  }

  function projectPaths(index) {
    return Object.keys(index.files).filter((path) => path.startsWith('projects/'));
  }

  /**
   * Свежее состояние прямо перед записью: файл и индекс одним запросом.
   * Одним — потому что оба ключа участвуют в каждой записи, и два round-trip
   * вместо одного удвоили бы окно, ради сужения которого всё и делается.
   */
  async function readForWrite(path) {
    const key = tasks.keyForPath(path);
    const { data, error } = await api.getKVManyByCurator(curatorJwt, clientId, [key, tasks.INDEX_KEY]);
    if (error) {
      throw new ToolError('upstream_error', `Не удалось перечитать ${path} перед записью: ${error.message}`);
    }
    const byKey = data || {};
    return {
      file: tasks.ensureFile(byKey[key], path),
      index: tasks.ensureIndex(byKey[tasks.INDEX_KEY]),
    };
  }

  const appendPrefetch = new Map();

  /**
   * Предзагрузка ревизии для дельта-записи.
   *
   * Стенограмма прицеплена к каждой записи в дневник и пишется после неё, а
   * чтение файла перед записью ни от результата дня, ни от текста блока не
   * зависит. Последовательно оно целиком лежало в ожидании куратора; запущенное
   * рядом с записью дня — не стоит ничего.
   *
   * Промис не бросает: предзагрузка это ускорение, а не источник правды. Если
   * чтение не удалось, writeFileDelta прочитает сам и отчитается об ошибке уже
   * своим путём.
   */
  function prefetchAppend(path) {
    const normalized = tasks.normalizePath(path);
    if (!normalized || !clientId) return;
    if (!isDeltaWritable(normalized)) return;
    if (appendPrefetch.has(normalized)) return;
    appendPrefetch.set(normalized, readForWrite(normalized).catch(() => null));
  }

  /** Ревизия из предзагрузки — разовая: устаревшая хуже лишнего чтения. */
  function takePrefetchedRead(path) {
    const hit = appendPrefetch.get(path);
    if (hit) appendPrefetch.delete(path);
    return hit || null;
  }

  function isDeltaWritable(path) {
    return tasks.isDeltaWritablePath(path) && typeof api.appendTasksFileByCurator === 'function';
  }

  /**
   * Файл под дельта-запись. На этом пути writeFileDelta перечитывает ревизию
   * сам, поэтому полное чтение здесь было вторым обращением за тем же файлом —
   * и платила за него каждая запись в дневник. Пустая заготовка подхватывает
   * текущую ревизию через rebase на первой же попытке.
   */
  async function openForAppend(path) {
    const normalized = tasks.normalizePath(path);
    if (!normalized) throw new ToolError('invalid_path', `Путь «${path}» не похож на файл задачника.`);
    if (!isDeltaWritable(normalized)) return readFile(normalized);
    requireClient();
    return tasks.ensureFile(null, normalized);
  }

  /**
   * Отказ вместо тихого затирания. Формулировка та же, что у tasks_patch:
   * модель должна понять не «сломалось», а «перечитай и повтори».
   */
  function staleWriteError(path, baseRev, currentRev) {
    return new ToolError(
      'stale_write_blocked',
      `Файл ${path} изменился с момента чтения (была ревизия ${baseRev}, сейчас ${currentRev}) — пишет кто-то ещё. Запись не сохранена: поверх неё пропала бы чужая правка. Перечитай файл (tasks_read) и повтори операцию на свежем тексте.`,
      { path, base_rev: baseRev, current_rev: currentRev },
    );
  }

  function indexHasEntry(index, file) {
    const entry = index.files[file.path];
    return !!entry && Number(entry.rev) >= Number(file.rev);
  }

  /**
   * След файла в индексе. Индекс общий на весь задачник, поэтому за него
   * дерутся даже записи в РАЗНЫЕ файлы: чужой батч кладёт свою копию индекса
   * целиком и уносит наш свежий след. Файл при этом цел, но пуллер о правке не
   * узнает — потеря молчаливая ровно так же.
   *
   * Чинится без участия модели: наша правка индекса — это добавление одной
   * записи в свежую копию, повтор идемпотентен и ничего не может затереть.
   */
  async function ensureIndexEntry(file, index, contextId) {
    let current = index;
    for (let attempt = 1; attempt <= WRITE_ATTEMPTS; attempt += 1) {
      if (indexHasEntry(current, file)) return current;
      const repaired = tasks.withIndexEntry(current, file, nowMs);
      const res = await api.upsertKVManyByCurator(curatorJwt, clientId, [
        { k: tasks.INDEX_KEY, v: repaired },
      ], contextId);
      if (!res.ok) throw new ToolError('save_failed', `Сервер отклонил запись индекса задачника: ${res.error}`);
      current = (await readForWrite(file.path)).index;
    }
    if (indexHasEntry(current, file)) return current;
    throw new ToolError(
      'index_write_blocked',
      `Текст ${file.path} сохранён, но след правки в индексе задачника раз за разом затирают из другой сессии. Пуллер её не заберёт: повтори запись, когда параллельная работа закончится.`,
      { path: file.path, rev: file.rev },
    );
  }

  /**
   * Запись файла: значение и индекс обновляются одним вызовом. Индекс без
   * файла или файл без индекса — расхождение, из-за которого пуллер либо не
   * заберёт правку, либо будет считать её потерянной.
   *
   * Между чтением файла в инструменте и этой записью проходит время, и в него
   * помещается чужая запись из другой сессии. Раньше она молча пропадала:
   * батч кладёт значение безусловно, ревизия у обоих получалась одна и та же,
   * а инструмент отвечал `ok`. Поэтому здесь три вещи.
   *
   * 1. Перед записью состояние перечитывается: ревизия разошлась — значит
   *    основа устарела.
   * 2. Что делать с расхождением, решает вызывающий. Дописывание можно
   *    безболезненно повторить на свежем тексте — для этого передаётся
   *    `rebase`. Всё, что опирается на номер строки из старого чтения
   *    (правка задачи, снятие слота, замена блока), повторять нельзя: строка
   *    уже уехала. Такие пути честно отказывают.
   * 3. После записи значение читается обратно. Совпавшая ревизия при чужом
   *    тексте — это ровно тот отпечаток, по которому потеря и была поймана:
   *    двое писали от одной основы, второй лёг поверх первого.
   *
   * Полноценного compare-and-swap на сервере нет (batch_upsert пишет
   * безусловно), поэтому окно не закрывается совсем — но проигравший всегда
   * видит, что его текста нет, и либо повторяет, либо отказывает вслух.
   */
  async function writeFileDelta(file, { mode, block }, { rebase = null } = {}) {
    const contextId = writeContext ? await writeContext(clientId) : null;
    let baseRev = Number(file.rev) || 0;
    const deltaBlock = String(block || '').trim();
    if (!deltaBlock) throw new ToolError('invalid_block', 'Пустой блок для дельта-записи.');

    for (let attempt = 1; attempt <= WRITE_ATTEMPTS; attempt += 1) {
      const before = (attempt === 1 ? await takePrefetchedRead(file.path) : null)
        || await readForWrite(file.path);
      if (before.file.rev !== baseRev) {
        if (!rebase) throw staleWriteError(file.path, baseRev, before.file.rev);
        baseRev = before.file.rev;
      }

      const res = await api.appendTasksFileByCurator(curatorJwt, clientId, {
        path: file.path,
        mode,
        block: deltaBlock,
        base_rev: baseRev,
      }, contextId);
      if (!res.ok && res.error === 'stale_rev') {
        if (!rebase) throw staleWriteError(file.path, baseRev, res.current_rev);
        baseRev = res.current_rev;
        continue;
      }
      if (!res.ok) throw new ToolError('save_failed', `Сервер отклонил дельта-запись ${file.path}: ${res.error}`);

      const after = await readForWrite(file.path);
      const expectedRev = Number(res.data && res.data.rev) || 0;
      if (expectedRev > 0 && after.file.rev !== expectedRev) {
        baseRev = after.file.rev;
        continue;
      }
      if (after.file.rev <= baseRev) {
        baseRev = after.file.rev;
        continue;
      }

      indexPromise = Promise.resolve(await ensureIndexEntry(after.file, after.index, contextId));
      return after.file;
    }

    throw new ToolError(
      'stale_write_blocked',
      `Не удалось дельта-записать ${file.path}: за ${WRITE_ATTEMPTS} попытки файл каждый раз успевали переписать из другой сессии. Ничего не сохранено. Повтори операцию, когда параллельная работа закончится.`,
      { path: file.path, attempts: WRITE_ATTEMPTS },
    );
  }

  async function writeFile(file, text, { rebase = null, delta = null } = {}) {
    // Единственная дверь наружу для всех пишущих инструментов, поэтому запрет
    // на чужие файлы стоит здесь, а не в каждом обработчике по отдельности.
    const guarded = tasks.ownerOnlyFile(file.path);
    if (guarded) {
      throw new ToolError('owner_only_file', tasks.ownerOnlyRefusal(guarded), { path: guarded });
    }
    if (delta && isDeltaWritable(file.path)) {
      return writeFileDelta(file, delta, { rebase });
    }
    if (tasks.estimateWritePayloadBytes(file.path, text) > tasks.TASKS_WRITE_PAYLOAD_LIMIT) {
      throw new ToolError(
        'payload_too_large',
        `Запись ${file.path} не влезает в лимит RPC (${tasks.TASKS_WRITE_PAYLOAD_LIMIT} байт). Для transcript/journal нужна дельта-запись — сообщи разработчику, если видишь это на checkpoint. Для projects/*.md это значит, что файл пора разгрузить: закрытые задачи в архив.`,
        { path: file.path },
      );
    }
    const contextId = writeContext ? await writeContext(clientId) : null;
    let baseRev = Number(file.rev) || 0;
    let nextText = text;

    for (let attempt = 1; attempt <= WRITE_ATTEMPTS; attempt += 1) {
      const before = await readForWrite(file.path);
      if (before.file.rev !== baseRev) {
        if (!rebase) throw staleWriteError(file.path, baseRev, before.file.rev);
        baseRev = before.file.rev;
        nextText = rebase(before.file.text);
      }

      const next = tasks.bumpFile(before.file, nextText, nowMs);
      const nextIndex = tasks.withIndexEntry(before.index, next, nowMs);
      const res = await api.upsertKVManyByCurator(curatorJwt, clientId, [
        { k: tasks.keyForPath(next.path), v: next },
        { k: tasks.INDEX_KEY, v: nextIndex },
      ], contextId);
      // Сервер отбил запись по ревизии: пока мы собирали текст, файл переписали
      // из другой сессии. Это тот же случай, что и расхождение baseRev выше, —
      // следующий круг перечитает файл и наложит правку на свежий текст.
      if (!res.ok && res.error === 'tasks_stale_rev') {
        if (!rebase) throw staleWriteError(file.path, baseRev, Number(res.currentRev) || 0);
        continue;   // baseRev не трогаем: круг выше сам увидит расхождение и пересоберёт текст
      }
      if (!res.ok) throw new ToolError('save_failed', `Сервер отклонил запись ${next.path}: ${res.error}`);

      const after = await readForWrite(file.path);
      // Ревизия выше нашей — кто-то писал уже поверх сохранённого; наш текст
      // до него дошёл. Ревизия наша, а текст чужой — нас затёрли.
      const survived = after.file.rev > next.rev
        || (after.file.rev === next.rev && after.file.text === next.text);
      if (!survived) {
        if (!rebase) {
          throw new ToolError(
            'stale_write_blocked',
            `Запись в ${file.path} не удержалась: параллельная сессия легла поверх неё той же ревизией ${next.rev}. Твоего изменения в файле НЕТ. Перечитай файл (tasks_read) и повтори операцию на свежем тексте.`,
            { path: file.path, base_rev: next.rev, current_rev: after.file.rev },
          );
        }
        baseRev = after.file.rev;
        nextText = rebase(after.file.text);
        continue;
      }

      indexPromise = Promise.resolve(await ensureIndexEntry(next, after.index, contextId));
      return next;
    }

    throw new ToolError(
      'stale_write_blocked',
      `Не удалось записать ${file.path}: за ${WRITE_ATTEMPTS} попытки файл каждый раз успевали переписать из другой сессии. Ничего не сохранено. Повтори операцию, когда параллельная работа закончится.`,
      { path: file.path, attempts: WRITE_ATTEMPTS },
    );
  }

  /**
   * Память прохода. Лежит отдельным ключом и намеренно НЕ попадает в индекс
   * задачника: индекс — это список файлов, которые пуллер выкладывает на диск,
   * а память прохода файлом не является и на диске ей делать нечего.
   */
  async function loadState() {
    requireClient();
    if (!statePromise) {
      statePromise = (async () => {
        const { data, error } = await api.getKVByCurator(curatorJwt, clientId, tasks.STATE_KEY);
        if (error) throw new ToolError('upstream_error', `Не удалось прочитать память прохода: ${error.message}`);
        return tasks.ensureState(data);
      })();
      statePromise.catch(() => { statePromise = null; });
    }
    return statePromise;
  }

  async function writeState(next) {
    const value = { ...next, updatedAt: nowMs };
    const contextId = writeContext ? await writeContext(clientId) : null;
    const res = await api.upsertKVManyByCurator(curatorJwt, clientId, [{ k: tasks.STATE_KEY, v: value }], contextId);
    if (!res.ok) throw new ToolError('save_failed', `Не удалось сохранить память прохода: ${res.error}`);
    statePromise = Promise.resolve(value);
    return value;
  }

  /**
   * Напоминание свести деньги за прошедший день — там, где утром и так
   * закрывают вчерашний день: на планёрке и в tasks_close_day.
   *
   * Три вещи здесь неслучайны.
   *
   * Первое: спрашивают только про завершённый день. Пока день идёт, «операций
   * нет» не значит ничего — трата случится через час, и признак будет врать
   * каждый вечер. За вчера всё уже случилось, и вносится оно один раз целиком.
   * Это его собственная правка от 2026-08-03.
   *
   * Второе: молчим, как только за день записана хоть одна операция. Приписка,
   * приходящая каждое утро независимо от того, сделал он или нет, перестаёт
   * читаться за неделю, и вместе с ней перестают читаться соседние.
   *
   * Третье: один вопрос на день. Дата спрошенного лежит в памяти прохода,
   * поэтому две подряд вызванные повестки не превращаются в два напоминания.
   * Память не сохранилась — напоминание всё равно уходит: лучше повторить,
   * чем промолчать про несведённый день.
   */
  /**
   * Круг простых вопросов для планёрки. Память прохода помнит показанное, чтобы
   * вечерняя планёрка не повторила утреннюю. Память не прочиталась или не
   * сохранилась — пятёрка всё равно уходит: повтор вопроса дешевле молчания, а
   * молчание здесь означает, что открытых меньше не станет.
   */
  async function simpleQuestionRound(questions, today_) {
    let state = null;
    try {
      state = await loadState();
    } catch {
      return tasks.pickSimpleQuestions(questions, tasks.ensureState(null), { today: today_ });
    }
    const round = tasks.pickSimpleQuestions(questions, state, { today: today_ });
    if (round.picked.length) {
      try {
        await writeState(tasks.rememberShownQuestions(state, {
          picked: round.picked,
          keys: round.keys,
          reset: round.round_reset,
          nowMs,
        }));
      } catch { /* ротация не имеет права ломать повестку */ }
    }
    return round;
  }

  async function moneyDayNudge(date) {
    try {
      const state = await loadState();
      if (state.money_nudge && state.money_nudge.date === date) return null;
      const file = await readFile(`money/${date.slice(0, 7)}.md`);
      const status = tasks.moneyDayStatus(file.text, date);
      const reminder = tasks.moneyDayReminder(status);
      if (!reminder) return null;
      try {
        await writeState({ ...state, money_nudge: { date, at: nowMs } });
      } catch { /* приписку это не отменяет — повтор дешевле молчания */ }
      return { reminder, status };
    } catch {
      return null;                 // напоминание не имеет права ломать вызов
    }
  }

  /**
   * Материал для ревизии: стенограммы окна и их несверенные хвосты.
   *
   * Окно, а не сегодняшний день: работа до двух ночи попадает во вчерашний
   * файл, а планёрку могли пропустить вовсе. Отметка о сверке лежит в самих
   * файлах, поэтому лишнего они не принесут — день без хвоста в блок не идёт.
   *
   * Читается всё одним батчем: семь отдельных round-trip ради приписки — это
   * дороже, чем сама повестка. Ошибка чтения блок не гасит: непрочитанная
   * стенограмма и несверенная выглядят одинаково — как повод посмотреть.
   */
  async function dayReviewRound(date) {
    const dates = Array.from(
      { length: tasks.REVIEW_WINDOW_DAYS },
      (_, i) => tasks.shiftDate(date, -i),
    );
    const transcriptPaths = dates.map((day) => tasks.transcriptPath(day));
    const dayPaths = dates.map((day) => `days/${day}.md`);
    let files = [];
    try {
      files = await readAll({ paths: [...transcriptPaths, ...dayPaths], max: transcriptPaths.length + dayPaths.length });
    } catch { files = []; }
    const byPath = new Map(files.map((file) => [file.path, file]));
    const entries = dates.map((day) => ({ date: day, file: byPath.get(tasks.transcriptPath(day)) || null }));
    const dayEntries = dates.map((day) => ({ date: day, file: byPath.get(`days/${day}.md`) || null }));
    return { entries, dayEntries, status: tasks.dayReviewStatus(entries, { date, dayEntries }) };
  }

  /**
   * Задача с её адресом на доске. Всё читающее отдаёт задачи только так: без
   * адреса вызывающему пришлось бы считать хэш самому, повторив у себя разбор
   * заголовка, — и однажды разойтись с доской.
   */
  function withAddress(task) {
    // Окно приклеивается здесь, в общей точке: через неё задачи проходят и в
    // списки, и в календарь, и в снимок доски. Разложить его по каждому
    // инструменту отдельно значило бы, что где-то оно молча потеряется — на
    // телефоне, например, где строку контекста никто не читает.
    const window = tasks.taskWindow(task.children);
    return {
      ...task,
      ...tasks.taskAddress(task.path, task.title),
      ...(window ? { window, signal: window.from } : {}),
    };
  }

  const tools = {
    async tasks_read(args = {}) {
      const file = await readFile(args.path);
      if (!file.text) {
        return {
          text: `Файл ${file.path} пустой или ещё не заведён.`,
          structured: { path: file.path, rev: file.rev, text: '', tasks: [] },
        };
      }
      // Текст файла отдаётся как есть, а рядом — список задач с адресами:
      // в самом markdown хэша нет, и по прочитанному файлу править задачу
      // было бы нечем. Разбор идёт по ПОЛНОМУ тексту, даже когда наружу уходит
      // только хвост: иначе у обрезанного файла половина задач просто исчезнет
      // из ответа, и править их будет нечем.
      const inFile = /^projects\//i.test(file.path)
        ? tasks.parseTasks(file).map((task) => {
          const { ref, hash, project } = tasks.taskAddress(file.path, task.title);
          return { ref, hash, project, title: task.title, line: task.line, done: task.done, waiting: task.waiting, due: task.due, priority: task.priority, tags: task.tags };
        })
        : [];

      const view = tasks.fileWindow(file.text, { maxChars: args.max_chars, fromLine: args.from_line });
      const head = `${file.path} (ревизия ${file.rev}${view.truncated ? `, показаны строки ${view.from_line}–${view.to_line} из ${view.total_lines}` : ''}):`;
      const tail = view.truncated
        ? `\n\n[Отдана только часть файла: ${view.shown_chars} символов из ${view.total_chars}. Дальше вверх — начало, его тут нет. Нужен кусок оттуда: tasks_search по словам из него или tasks_read с from_line.]`
        : '';
      return {
        text: `${head}\n\n${view.text}${tail}`,
        structured: {
          path: file.path,
          rev: file.rev,
          text: view.text,
          tasks: inFile,
          truncated: view.truncated,
          from_line: view.from_line,
          to_line: view.to_line,
          total_lines: view.total_lines,
          total_chars: view.total_chars,
        },
      };
    },

    async tasks_search(args = {}) {
      const query = String(args.query || '').trim();
      if (!query) throw new ToolError('invalid_query', 'Нужны слова для поиска.');
      // Прямой поиск словами — единственное место, где разовые отчёты читаются
      // наравне со всем: «искал и не нашёл» имеет право прозвучать, только
      // если искали действительно везде.
      //
      // Потолок здесь свой и много выше прохода: 26 отчётов пролезали восьмёркой
      // по алфавиту, и «по X ничего нет» было неправдой в восемнадцати случаях
      // из двадцати шести. Стоит это не токенов модели, а одного батча: наружу
      // из поиска уходят найденные строки, а не тексты файлов.
      const { files, skipped } = await readAllWithMeta({ reports: true, max: SEARCH_MAX });
      // Ссылки собираются один раз и отдаются поиску: без них связанная руками
      // запись остаётся внизу, потому что общих слов у пары обычно нет.
      const matches = tasks.searchFiles(files, query, {
        limit: args.limit || 40,
        today: today(),
        linkPairs: tasks.linkEndpointPairs(files),
      });
      // Непрочитанное называется вслух и с именами файлов: иначе «ничего нет»
      // и «не смотрел» звучат одинаково, а решение по ним принимается разное.
      const unread = skipped.length
        ? ` Не поместилось в проход ${skipped.length}: ${skipped.slice(0, 5).join(', ')}${skipped.length > 5 ? ' и другие' : ''} — если ответ может быть там, прочитай их через tasks_read.`
        : '';
      return {
        text: matches.length
          ? `Нашёл ${matches.length} совпадений по «${query}»: ${[...new Set(matches.map((m) => m.path))].join(', ')}.${unread}`
          : `По «${query}» в прочитанном ничего нет${skipped.length ? '' : ' — а прочитан весь задачник'}.${unread}`,
        structured: { query, matches, searched: files.length, skipped },
      };
    },

    /**
     * Сборка контекста темы. Открытые вопросы и обязательства идут первыми:
     * методичка требует поднимать их до собственных новых вопросов, иначе
     * ассистент второй раз спрашивает то, что уже висит с прошлой недели.
     */
    async tasks_context(args = {}) {
      const topic = String(args.topic || args.phrase || '').trim();
      if (!topic) throw new ToolError('invalid_topic', 'Нужна фраза или тема.');
      if (tasks.diaryTopicUsesAddressAlias(topic)) {
        const canon = (() => {
          const m = String(topic).toLowerCase().match(/(?:^|[^\p{L}\p{N}])(мне|меня|мной|мною|себе|себя|собой|жене|жена|жены|жену|женой|цыпе|цыпа|цыпы|цыпу)(?:[^\p{L}\p{N}]|$)/u);
          return m ? tasks.addressAliasCanon(m[1]) : 'мне';
        })();
        return {
          text: [
            'tasks_context здесь не нужен: фраза про дневник/адресацию с алиасом «мне»/«жене»/«жена»/«цыпе».',
            `Передавай client=${canon} прямо в heys_log_meal / heys_create_product / heys_search_products / heys_list_meal_presets — сервер развернёт в client_id.`,
            'heys_list_clients и tasks_learn — только если алиас неизвестен.',
            'Параметры MCP (from_product_id и др.) — в описании инструмента, не grep репо.',
          ].join(' '),
          structured: { skip_reason: 'diary_addressing_use_client_param', topic, suggested_client: canon },
        };
      }
      const files = await readAll({});

      // Адрес задачи с доски — самый точный вход: и когда он передан целиком,
      // и когда просто упомянут внутри фразы («что там по kinderly/8e3572»).
      const addresses = tasks.parseAddress(topic)
        ? [tasks.parseAddress(topic)]
        : tasks.findAddresses(topic);
      const seeds = addresses
        .map((address) => tasks.findTaskByAddress(files, address))
        .filter(Boolean);

      // Значимые слова выделяются здесь, а не моделью: решение «что искать» —
      // это ровно то место, где промахиваются и потом перебирают запросы по
      // одному. Фраза приходит целиком, разбор её делает код.
      const { terms, dropped } = tasks.topicTerms(topic);

      const matchingTasks = [...seeds];
      const scored = [];
      for (const file of files.filter((f) => f.path.startsWith('projects/'))) {
        for (const task of tasks.parseTasks(file)) {
          if (seeds.some((s) => s.path === task.path && s.line === task.line)) continue;
          const { score, hit } = tasks.matchTerms(`${task.title} ${task.children.join(' ')}`, terms);
          if (!score) continue;
          scored.push({ ...task, score, matched: hit });
        }
      }
      scored.sort((a, b) => b.score - a.score);
      matchingTasks.push(...scored.slice(0, 12));
      // Адрес — у каждой найденной задачи: иначе снять по ней вопрос можно
      // только пересчитав хэш на своей стороне.
      const foundTasks = matchingTasks.map(withAddress);

      /**
       * Связанное по явной ссылке. Это главное отличие от поиска: совпадение
       * слов находит то, что похоже, а ссылка — то, что человек сам связал.
       * Смотрим в обе стороны: ссылку ставили один раз, и с той стороны, где
       * её не писали, связь всё равно должна быть видна.
       */
      const allLinks = tasks.collectLinks(files);
      const linked = [];
      const seenLink = new Set();
      for (const task of matchingTasks.slice(0, 8)) {
        const project = tasks.projectKeyForPath(task.path);
        const hash = tasks.taskHash(project, task.title);
        const { outgoing, incoming } = tasks.linksFor(files, { project, hash }, allLinks);
        for (const link of outgoing) {
          const id = `out:${project}/${hash}:${link.ref}`;
          if (seenLink.has(id)) continue;
          seenLink.add(id);
          linked.push({ direction: 'ссылается на', from: `${project}/${hash}`, from_title: task.title, ...link });
        }
        for (const link of incoming) {
          const id = `in:${project}/${hash}:${link.path}:${link.line}`;
          if (seenLink.has(id)) continue;
          seenLink.add(id);
          linked.push({ direction: 'ссылается сюда', to: `${project}/${hash}`, to_title: task.title, ...link });
        }
      }

      // Записи журнала ранжируются не только по словам: свежая запись и
      // формулировка решения весят больше пересказа, а строка, из которой
      // руками поставлена ссылка на найденную задачу, поднимается отдельно —
      // ссылки резолвятся по ВСЕМ файлам, иначе цель ссылки не найдётся.
      // Деньги входят в корпус наравне с журналом. Без них целый класс
      // вопросов не решался основным путём вовсе: «сколько отдал за новую
      // батарею» лежит операцией в money/, и tasks_context честно отвечал
      // «ничего не нашлось», хотя сумма записана. Файл на месяц, как журнал,
      // — чтение почти ничего не стоит.
      // Ротация (07.08): переполненный journal уезжает в archive/journal_*_partN —
      // это тот же корпус выводов, иначе старые итоги месяца выпадали из автоконтекста.
      const journalHits = tasks.searchFiles(
        files.filter((f) => tasks.isJournalCorpusPath(f.path) || tasks.isMoneyCorpusPath(f.path)),
        topic,
        {
          limit: 10,
          context: 3,
          terms,
          any: terms.length > 1,
          today: today(),
          linkPairs: tasks.linkEndpointPairs(files, allLinks),
          related: matchingTasks.map((t) => ({ path: t.path, line: t.line })),
        },
      );
      // Сырьё стенограммы — отдельно и только по словам. Не выводы: вес 0,
      // в разбор как «решили» не поднимается. Нужно дочитать детали — tasks_read.
      const transcriptHits = tasks.searchFiles(
        files.filter((f) => tasks.isTranscriptCorpusPath(f.path)),
        topic,
        {
          limit: 5,
          context: 2,
          terms,
          any: terms.length > 1,
          today: today(),
        },
      );
      const open = tasks.collectOpenQuestions(files)
        .filter((q) => tasks.matchTerms(`${q.task} ${q.question}`, terms).score > 0);
      const people = tasks.collectPeopleThreads(files)
        .filter((p) => tasks.matchTerms(`${p.task} ${p.text}`, terms).score > 0);

      // Окружение найденного: проект целиком и время в днях. Без него ответ
      // строится по обрывкам строк, и остальное приходится домысливать.
      const projects = tasks.projectNeighborhood(files, matchingTasks);
      const slots = tasks.slotsAround(
        files,
        foundTasks.map((t) => t.ref).filter(Boolean),
        terms,
        { from: tasks.taskDay(nowMs) },
      );

      // Как он решает — возвращается всегда и целиком. Смысл этой памяти в
      // том, что её не надо вспоминать отдельным вызовом: правило, о котором
      // помнят через раз, хуже отсутствующего.
      // Устаревшее в разбор не идёт: отменённое значение, приехавшее наравне с
      // действующим, — это не история, а второй правильный ответ. Историю он
      // читает в самом файле, где она и лежит с датой.
      const prefsFile = files.find((f) => f.path === tasks.PREFS_PATH) || null;
      const preferences = tasks.activePreferences(tasks.parsePreferences(prefsFile));

      /**
       * Отметка «пригодилось». Считается не «пришло в ответ» — приходят все
       * записи и всегда, такой счётчик мерил бы число вызовов, — а «попало по
       * словам в то, что он сейчас сказал». Из-за этого запись обычно не
       * трогается вовсе, и лишней записи в облако на каждую реплику нет.
       *
       * Счётчик нужен ровно для одного: на планёрке отличить память, которая
       * работает, от той, что просто лежит. Сломаться он права не имеет —
       * tasks_context читающий, и неудачная отметка не должна стоить разбора.
       */
      const relevant = preferences.filter((p) => {
        // Синонимы участвуют наравне с самой записью: он говорит «до зала»,
        // а в факте написано «студия» — без них запись не поднимется и будет
        // выглядеть ни разу не пригодившейся, то есть уедет на вычёркивание.
        const text = `${p.note} ${p.question || ''} ${(p.aliases || []).join(' ')}`;
        // Слова сверяются в обе стороны. Приведение к основе тут длинозависимое
        // («лендинг» и «лендингу» дают разные основы), и односторонняя проверка
        // молча промахивалась бы на падежах — то есть считала бы работающую
        // запись ни разу не пригодившейся.
        //
        // Плюс сырая фраза: «мне»/«себе» — TOPIC_STOP_WORDS, из terms выпадают,
        // и адресация дневника на «запиши мне» никогда не попадала в «Из памяти».
        p.relevant = tasks.matchTerms(text, terms).score > 0
          || tasks.matchTerms(topic, tasks.topicTerms(text).terms).score > 0
          || tasks.preferenceHitsRawTopic(p, topic);
        return p.relevant;
      });
      if (relevant.length && prefsFile) {
        try {
          await writeFile(
            prefsFile,
            tasks.bumpPreferenceCounter(prefsFile.text, relevant, { field: 'пригодилось', date: today() }),
          );
          for (const entry of relevant) entry.used = { count: (entry.used?.count || 0) + 1, date: today() };
        } catch (_) { /* отметка полезности не имеет права ломать чтение */ }
      }

      const parts = [];
      if (open.length) parts.push(`открытых вопросов: ${open.length}`);
      if (foundTasks.length) parts.push(`задач: ${foundTasks.length}`);
      if (slots.length) parts.push(`уже стоит в днях: ${slots.length}`);
      if (linked.length) parts.push(`связанного по ссылкам: ${linked.length}`);
      if (journalHits.length) parts.push(`записей в журнале: ${journalHits.length}`);
      if (transcriptHits.length) parts.push(`сырья стенограммы: ${transcriptHits.length}`);
      if (people.length) parts.push(`обязательств перед людьми: ${people.length}`);

      // Слова, по которым искали, возвращаются всегда. Без них непонятно,
      // почему контекст не нашёлся, и модель начинает гадать и перебирать
      // запросы — то самое поведение, от которого этот разбор и уводит.
      const words = terms.map((t) => t.word);
      const searchedBy = words.length ? ` Искал по словам: ${words.join(', ')}.` : '';

      /**
       * Подошедшая память печатается прямо в текст, а не только уезжает в
       * structured. Ради фактов эта память и заводилась: на «какая у меня
       * машина» ни одной задачи по словам не найдётся, и без этого блока
       * инструмент честно отвечал «ничего не нашлось» — при том что ответ
       * лежал в том же самом ответе, этажом ниже. Клиенту в content уходит
       * только text (lib/mcp.js), так что молчание тут равно потере факта.
       */
      // Самая длинная живая запись памяти на 04.08 — 695 знаков; потолок взят
      // с запасом, чтобы факт доезжал целиком, а не до середины.
      const PREF_NOTE_CAP = 800;
      const recalled = relevant
        .map((p) => {
          // Целиком, а не первым куском: в самом факте тире обычное дело
          // («Машина — Hyundai Solaris»), и обрезка по нему оставляла бы
          // от записи одно слово. Опора уже отделена разбором и не печатается.
          //
          // Потолок высокий и режет по границе предложения. Прежние 160 знаков
          // отсекали ровно то, ради чего запись заводилась: у факта про районы
          // за срезом оставались и «живут сейчас на юге», и сетка тренировок по
          // дням, то есть запись формально доезжала, а ответ на «где мы живём»
          // — нет. Обрыв на полуслове здесь хуже длинной строки: человек не
          // видит, что его обрезали, и считает прочитанное всей записью.
          const note = String(p.note || '').trim();
          if (note.length <= PREF_NOTE_CAP) return `— ${p.kind}: ${note}`;
          const head = note.slice(0, PREF_NOTE_CAP);
          const cut = Math.max(head.lastIndexOf('. '), head.lastIndexOf('; '));
          const shown = cut > PREF_NOTE_CAP * 0.5 ? head.slice(0, cut + 1) : head;
          return `— ${p.kind}: ${shown.trim()}…`;
        })
        .join('\n');
      const memory = recalled ? `\nИз памяти:\n${recalled}` : '';
      if (relevant.length) parts.push(`записей в памяти: ${relevant.length}`);

      return {
        text: parts.length
          ? `По «${topic}» — ${parts.join(', ')}.${searchedBy}${memory}`
          : `По «${topic}» в задачнике ничего не нашлось.${searchedBy}`,
        structured: {
          topic,
          terms: words,
          ignored: dropped,
          refs: addresses.map((a) => `${a.project}/${a.hash}`),
          open_questions: open,
          tasks: foundTasks,
          projects,
          slots,
          preferences,
          linked,
          journal: journalHits,
          transcript: transcriptHits,
          people,
        },
      };
    },

    async tasks_list(args = {}) {
      const index = await loadIndex();
      const wanted = args.project
        ? [`projects/${String(args.project).toLowerCase().replace(/\.md$/i, '')}.md`]
        : projectPaths(index);
      const files = await readAll({ paths: wanted });

      const today = tasks.taskDay(nowMs);
      const tag = args.tag ? String(args.tag).replace(/^#/, '').toLowerCase() : null;

      const all = files.flatMap((file) => tasks.parseTasks(file))
        .filter((task) => !task.done)
        .filter((task) => !tag || task.tags.some((t) => t.toLowerCase() === tag))
        .map(withAddress);

      const overdue = all.filter((task) => task.due && task.due < today);
      const dueToday = all.filter((task) => task.due === today);
      const next = all.filter((task) => task.tags.some((t) => t.toLowerCase() === 'next'));
      // «Требует решения» — то, что ждёт его ответа. Без отдельного списка эти
      // задачи не попадали никуда: срока у развилки обычно нет, #next тоже, —
      // и «покажи, что требует решения» приходилось закрывать чтением файлов
      // мимо инструмента.
      // Отложенное решением сюда не идёт: «вернуться: 2026-09-01» — это уже
      // данный ответ «не сейчас», а не ожидание ответа. Доска сворачивает такие
      // задачи так же; разойтись им нельзя, иначе перенос виден в одном месте и
      // не виден в другом. Дата пришла — задача возвращается сама.
      const blocked = all.filter((task) => task.tags.some((t) => t.toLowerCase() === 'blocked')
        || task.children.some((c) => /^открыто:/i.test(c)))
        .filter((task) => {
          const back = tasks.taskBackDate(task.children, { today });
          return !(back && back > today);
        });

      return {
        text: `Просрочено: ${overdue.length}, на сегодня: ${dueToday.length}, в #next: ${next.length}, требует решения: ${blocked.length}, активных всего: ${all.length}.`,
        structured: {
          project: args.project || null,
          tag: tag || null,
          overdue,
          due_today: dueToday,
          next,
          blocked,
          total_active: all.length,
        },
      };
    },

    /**
     * Загруженность вперёд. Это второе из двух чтений, без которых на вопрос
     * «когда уехать» можно было ответить только ощущением: поиск по словам
     * находит названное теми же словами, а свободная неделя никак не названа.
     *
     * Дни, повторы и проекты читаются одной пачкой: тридцать дней по одному
     * ключу — это тридцать сетевых вызовов на каждый такой вопрос.
     */
    async tasks_calendar(args = {}) {
      const from = args.from ? String(args.from).trim() : today();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(from)) {
        throw new ToolError('invalid_from', `Дата «${args.from}» не в формате YYYY-MM-DD.`);
      }
      const raw = args.days === undefined || args.days === null ? 30 : Number(args.days);
      if (!Number.isFinite(raw) || raw < 1) throw new ToolError('invalid_days', 'Сколько дней вперёд — целое число от 1.');
      const span = Math.min(Math.round(raw), 60);
      const dates = Array.from({ length: span }, (_, i) => tasks.shiftDate(from, i));
      const till = dates[dates.length - 1];

      const index = await loadIndex();
      const dayPaths = dates.map((date) => `days/${date}.md`);
      const projects = projectPaths(index);
      const wanted = [...dayPaths, 'days/recurring.md', ...projects];
      const files = await readAll({ paths: wanted, max: wanted.length });
      const byPath = new Map(files.map((file) => [file.path, file]));

      const recurring = tasks.parseRecurringSlots((byPath.get('days/recurring.md') || {}).text || '');

      // Дедлайны — это то, что придётся двигать вместе с датами поездки, поэтому
      // они висят прямо на дне, а не отдельным списком «где-то в проектах».
      const dueByDate = new Map();
      for (const path of projects) {
        const file = byPath.get(path);
        if (!file) continue;
        for (const task of tasks.parseTasks(file)) {
          if (task.done || !task.due) continue;
          const window = tasks.taskWindow(task.children);
          const withRef = withAddress(task);
          // Задача с окном висит на двух днях: когда её можно начинать и когда
          // край. Одним днём на конце окна она в календаре выглядит как дело
          // последнего дня, хотя делать её надо было раньше. Всеми днями окна —
          // замусорила бы полмесяца на «второй половине августа».
          const marks = window
            ? [[window.from, 'окно открывается'], [task.due, 'край окна']]
            : [[task.due, null]];
          for (const [date, note] of marks) {
            if (date < from || date > till) continue;
            if (!dueByDate.has(date)) dueByDate.set(date, []);
            const already = dueByDate.get(date).find((row) => row.ref === withRef.ref);
            if (already) continue;
            dueByDate.get(date).push({
              ref: withRef.ref, project: withRef.project, title: task.title, priority: task.priority,
              ...(note ? { window: `${window.from}..${window.to}`, note } : {}),
            });
          }
        }
      }

      const days = dates.map((date) => {
        const load = tasks.dayLoad({ date, text: (byPath.get(`days/${date}.md`) || {}).text || '', recurring });
        return { ...load, due: dueByDate.get(date) || [] };
      });

      const weeks = tasks.weekLoad(days);
      const anchors = tasks.anchorSlots(days);
      const freeDays = days.filter((d) => d.busy_minutes === 0 && !d.due.length).map((d) => d.date);
      // День с дедлайном свободным не считается, даже если слотов в нём нет:
      // именно он и окажется тем, что «придётся подвинуть».
      const stretches = tasks.freeStretches(days.map((d) => ({
        date: d.date, busy_minutes: d.due.length ? Math.max(d.busy_minutes, 1) : d.busy_minutes,
      })));
      // «Плотнее/свободнее всего» сравнивается только между целыми неделями:
      // первая и последняя недели окна почти всегда обрезаны, и обрезок вида
      // «одно воскресенье» выигрывал бы звание самой свободной недели всегда.
      // Целых недель может не быть вовсе (окно короче) — тогда сравниваем что есть.
      const full = weeks.filter((w) => w.full);
      const sorted = [...(full.length ? full : weeks)].sort((a, b) => b.busy_minutes - a.busy_minutes);
      const busiest = sorted[0] || null;
      const quietest = sorted[sorted.length - 1] || null;

      // Занятые ресурсы называются рядом со свободным временем: «свободно
      // 12:00–15:00, но ребёнок с тобой и без машины» — это другой ответ, чем
      // просто «свободно». Вывод из этого делает он: что достижимо без машины
      // и что делается с ребёнком, в коде не зашито.
      const withResources = days.filter((d) => d.resources.length);
      const resourceLine = withResources.slice(0, 3).map((d) => {
        const what = d.resources
          .map((r) => `${r.from}–${r.to} ${r.resource}${r.whose ? ` (${r.whose})` : ''}`)
          .join(', ');
        return `${d.date}: ${what}`;
      }).join('; ');

      const hours = (m) => Math.round((m / 60) * 10) / 10;
      const summary = [
        `${from}…${till}: свободных дней ${freeDays.length} из ${span}`,
        stretches.length ? `подряд: ${stretches.map((s) => `${s.from}…${s.to} (${s.days} дн.)`).join(', ')}` : 'подряд свободных дней нет',
        busiest ? `плотнее всего неделя с ${busiest.start} (${hours(busiest.busy_minutes)} ч)` : null,
        quietest && busiest && quietest.start !== busiest.start ? `свободнее всего с ${quietest.start} (${hours(quietest.busy_minutes)} ч)` : null,
        anchors.length ? `якоря: ${anchors.slice(0, 5).map((a) => `${a.title} (${a.weekdays.join(',') || '—'})`).join('; ')}` : 'повторяющегося ничего не видно',
        dueByDate.size ? `дедлайнов в окне: ${[...dueByDate.values()].reduce((n, x) => n + x.length, 0)}` : 'дедлайнов в окне нет',
        resourceLine
          ? `занято у него самого${withResources.length > 3 ? ` (первые 3 дня из ${withResources.length})` : ''} — ${resourceLine}`
          : null,
      ].filter(Boolean).join('. ');

      return {
        text: `${summary}.`,
        structured: {
          from, to: till, days, weeks, anchors,
          free_days: freeDays,
          free_stretches: stretches,
          busiest_week: busiest ? busiest.start : null,
          quietest_week: quietest ? quietest.start : null,
        },
      };
    },

    /**
     * Картина денег. Честность здесь важнее полноты: лимит «?» не превращается
     * в число, месяц без доходов помечается односторонним, а взносы в подушку
     * не выдаются за «доступно на поездку» — он свою подушку так не определял.
     */
    async tasks_budget(args = {}) {
      const month = args.month ? String(args.month).trim() : today().slice(0, 7);
      if (!/^\d{4}-\d{2}$/.test(month)) {
        throw new ToolError('invalid_month', `Месяц «${args.month}» не в формате YYYY-MM.`);
      }
      const contour = args.contour ? String(args.contour).replace(/^~/, '').trim().toLowerCase() : null;

      const index = await loadIndex();
      const monthPaths = [...new Set([
        `money/${month}.md`,
        ...Object.keys(index.files).filter((path) => /^money\/\d{4}-\d{2}\.md$/i.test(path)),
      ])];
      const wanted = [...monthPaths, 'money/budget.md', 'money/recurring.md'];
      const files = await readAll({ paths: wanted, max: wanted.length });
      const byPath = new Map(files.map((file) => [file.path, file.text]));

      const text = byPath.get(`money/${month}.md`) || '';
      const isCurrent = month === today().slice(0, 7);
      const picture = tasks.budgetPicture({
        month,
        text,
        budget: byPath.get('money/budget.md') || '',
        recurring: byPath.get('money/recurring.md') || '',
        // «Ещё спишется до конца месяца» имеет смысл только для текущего
        // месяца: в прошедшем всё уже списалось, и прогноз там был бы враньём.
        today: isCurrent ? today() : null,
        contour,
        months: monthPaths.map((path) => ({ month: path.slice(6, 13), text: byPath.get(path) || '' })),
      });

      const over = picture.limits.filter((l) => l.measurable && l.over > 0);
      const parts = [
        `${month}: расходов ${picture.spent} ₽`,
        `из них потребление ${picture.split.consumption} ₽, кредиты ${picture.split.debt} ₽, в подушку ${picture.split.cushion} ₽`,
        `доходов ${picture.income} ₽`,
        contour ? `по ~${contour} ${picture.contour.spent} ₽` : null,
        picture.balance ? `остаток на ${picture.balance.date} — ${picture.balance.amount} ₽` : 'остаток на счетах не замерян',
        picture.recurring_ahead ? `до конца месяца спишется само ещё ~${picture.recurring_ahead} ₽` : null,
        picture.travel.month ? `по ~travel за месяц ${picture.travel.month} ₽` : 'по ~travel в этом месяце ничего',
        picture.cushion.monthly !== null
          ? `в подушку ${picture.cushion.month} из ${picture.cushion.monthly} ₽ за месяц, накоплено ${picture.cushion.total} ₽${picture.cushion.goal !== null ? ` из цели ${picture.cushion.goal} ₽` : ''}`
          : `в подушку ${picture.cushion.month} ₽ за месяц`,
      ].filter(Boolean);

      // Дальше — ровно то, чего в данных нет. Это не оговорки для приличия: без
      // них вывод по бюджету читается как полный, хотя половины входа не было.
      const gaps = [
        picture.one_sided
          ? 'Доходов за месяц в записях нет — вывод односторонний, «хватает или нет» отсюда не следует.'
          : null,
        picture.unmeasured.length
          ? `Лимит не задан (${picture.unmeasured.join(', ')}) — отклонение мерить нечем, это его решение, а не пропуск.`
          : null,
        over.length
          ? `Сверх лимита: ${over.map((l) => `${l.contour} на ${l.over} ₽`).join(', ')}.`
          : null,
        'Подушка — сбережения, а не бюджет поездки: называть её «доступно на поездку» нельзя, он так её не определял.',
      ].filter(Boolean);

      return {
        text: `${parts.join(', ')}. ${gaps.join(' ')}`,
        structured: { ...picture, contour_key: contour, gaps },
      };
    },
  };

  Object.assign(tools, {
    async tasks_capture(args = {}) {
      const text = String(args.text || '').trim();
      if (!text) throw new ToolError('invalid_text', 'Нужен текст задачи.');

      const project = args.project ? String(args.project).toLowerCase().replace(/\.md$/i, '') : null;
      const path = project ? `projects/${project}.md` : 'INBOX.md';
      const file = await readFile(path);

      const priority = args.priority ? String(args.priority).toUpperCase() : 'P2';
      if (!/^P[123]$/.test(priority)) throw new ToolError('invalid_priority', 'Приоритет — P1, P2 или P3.');
      if (args.due && !/^\d{4}-\d{2}-\d{2}$/.test(args.due)) {
        throw new ToolError('invalid_due', `Срок «${args.due}» не в формате YYYY-MM-DD.`);
      }
      // Новая задача с неточным сроком заводится именно здесь, а не правкой
      // потом: без окна на этом шаге «в начале следующей недели» превращается
      // в задачу вовсе без срока, и она не всплывает нигде.
      const window = parseWindowArg(args.window);

      const today = tasks.taskDay(nowMs);
      const tags = (args.tags || []).map((t) => `#${String(t).replace(/^#/, '')}`);
      const parts = [`- [ ] ${priority} ${text}`];
      const due = window ? window.to : args.due;
      if (due) parts.push(`due:${due}`);
      parts.push(...tags, `^${today}`);
      const line = window ? `${parts.join(' ')}\n  - окно: ${window.from}..${window.to}` : parts.join(' ');

      // Дописывание адресуется разделом, а не номером строки, поэтому его
      // безопасно повторить на свежем тексте: чужая задача, приехавшая между
      // чтением и записью, останется на месте, наша встанет следом.
      const put = (text) => (project
        ? tasks.appendToSection(text, line, '## Задачи')
        : tasks.appendBlock(text, line));
      const saved = await writeFile(file, put(file.text), { rebase: put });

      const title = tasks.taskTitle(line.split('\n')[0]);
      const hash = tasks.taskHash(tasks.projectKeyForPath(path), title);
      const when = window
        ? `, окно ${window.from}..${window.to}, срок ${window.to}`
        : (due ? `, срок ${due}` : '');
      return {
        text: `Положил в ${saved.path}: ${priority} ${title}${when}. Ссылка: ${tasks.projectKeyForPath(path)}/${hash}`,
        structured: { path: saved.path, rev: saved.rev, hash, title, priority, due: due || null, window: window || null, tags },
      };
    },

    /**
     * Правка задач на доске.
     *
     * Батч здесь не удобство, а устранение основной статьи расхода: замер
     * 18–20.08 по `tasks_mcp_trace` показал 51 вызов `tasks_update` за сутки и
     * серии до тринадцати подряд на одну реплику. Каждый вызов — это круг
     * «модель → функция → модель» (≈13 с ожидания по трейсу) плюс чтение и
     * запись файла проекта. Тринадцать правок одного файла — это тринадцать
     * его перезаписей подряд, хотя достаточно одной.
     *
     * Поэтому правки одного проекта применяются к тексту по очереди и
     * сохраняются одним `writeFile`. Строку задачи каждый раз ищем заново: от
     * предыдущей правки в файле могли появиться вложенные строки, и номер
     * строки, снятый до неё, уже указывает не туда.
     *
     * Fail closed: любая непринятая правка роняет весь вызов, файл не
     * сохраняется. Иначе получается наполовину применённый батч, о котором
     * модель отчитается как о выполненном.
     */
    async tasks_update(args = {}) {
      const normalizeProject = (value) => String(value || '').toLowerCase().replace(/\.md$/i, '');
      const batch = Array.isArray(args.updates) ? args.updates : null;
      if (batch && !batch.length) {
        throw new ToolError('invalid_updates', 'updates пустой — передай хотя бы одну правку или используй hash.');
      }
      const items = batch || [args];
      const fallbackProject = normalizeProject(args.project);

      const byProject = new Map();
      for (const item of items) {
        const project = normalizeProject(item && item.project) || fallbackProject;
        if (!project) throw new ToolError('invalid_project', 'Нужен проект задачи.');
        if (!item || !item.hash) throw new ToolError('invalid_hash', 'Нужен хэш задачи с доски.');
        if (!byProject.has(project)) byProject.set(project, []);
        byProject.get(project).push({ ...item, project });
      }

      /** Одна правка над текстом файла. Возвращает новый текст и что изменилось. */
      const applyOne = (text, item, filePath) => {
        const file = { path: filePath, text };
        const found = tasks.findTaskByHash(file, item.hash);
        if (!found) {
          throw new ToolError('task_not_found', `В ${filePath} нет задачи с хэшем ${item.hash}. Возьми актуальный через tasks_list.`);
        }

        // Окно и срок ставятся одним движением: срок — всегда поздняя граница.
        // Врозь они разъезжаются руками, и задача с окном «10-12» получает срок
        // на 15-е, то есть окно перестаёт значить хоть что-нибудь.
        const window = parseWindowArg(item.window);

        const lines = text.split('\n');
        let changedWindowDropped = false;
        let patched;
        try {
          patched = tasks.applyTaskPatch(lines[found.line], {
            state: item.state,
            due: window ? window.to : item.due,
            priority: item.priority ? String(item.priority).toUpperCase() : undefined,
            addTags: item.add_tags,
            removeTags: item.remove_tags,
          });
        } catch (e) {
          throw new ToolError('invalid_field', `Не могу применить правку: ${e.message}`);
        }

        let nextText = [...lines.slice(0, found.line), patched, ...lines.slice(found.line + 1)].join('\n');
        // Старое окно снимается в обоих случаях: при новом окне — чтобы не копить
        // две разные правды под одной задачей, при обычном сроке — потому что
        // точность и появилась, окну больше нечего уточнять.
        if (window || (item.due !== undefined && item.due !== null && String(item.due).trim() !== '')) {
          const kept = nextText.split('\n');
          const drop = [];
          for (let i = found.line + 1; i < kept.length; i += 1) {
            const raw = kept[i];
            if (!raw.trim() || !/^\s/.test(raw)) break;
            if (tasks.taskWindow([raw.trim().replace(/^[-*]\s+/, '')])) drop.push(i);
          }
          for (const i of drop.reverse()) kept.splice(i, 1);
          nextText = kept.join('\n');
          if (window) nextText = tasks.appendChild(nextText, found.line, `окно: ${window.from}..${window.to}`);
          else if (drop.length) changedWindowDropped = true;
        }
        if (item.note) nextText = tasks.appendChild(nextText, found.line, String(item.note).trim());
        if (nextText === text) {
          throw new ToolError('nothing_to_update', batch
            ? `Правка ${item.project}/${item.hash} ничего не меняет — убери её из updates.`
            : 'Не передано ни одного изменения.');
        }

        const changed = [];
        if (item.state) changed.push(`состояние → ${item.state}`);
        if (window) changed.push(`окно → ${window.from}..${window.to}, срок → ${window.to}`);
        else if (item.due !== undefined) changed.push(item.due ? `срок → ${item.due}${changedWindowDropped ? ', окно снято' : ''}` : 'срок снят');
        if (item.priority) changed.push(`приоритет → ${item.priority}`);
        if (item.add_tags?.length) changed.push(`теги +${item.add_tags.join(', ')}`);
        if (item.remove_tags?.length) changed.push(`теги −${item.remove_tags.join(', ')}`);
        if (item.note) changed.push('добавлена строка контекста');

        return { text: nextText, changed, title: found.parsed.title };
      };

      const updated = [];
      const paths = [];
      let lastSaved = null;
      for (const [project, patches] of byProject) {
        const file = await readFile(`projects/${project}.md`);
        let text = file.text;
        const done = [];
        for (const item of patches) {
          const step = applyOne(text, item, file.path);
          text = step.text;
          done.push({ hash: item.hash, project, title: step.title, changed: step.changed });
        }
        lastSaved = await writeFile(file, text);
        paths.push(lastSaved.path);
        updated.push(...done);
      }

      const line = (row) => `${row.project}/${row.hash} · ${row.title}: ${row.changed.join('; ')}.`;
      if (!batch) {
        const only = updated[0];
        return {
          text: line(only),
          structured: {
            path: lastSaved.path, rev: lastSaved.rev, hash: only.hash, title: only.title, changed: only.changed, updated,
          },
        };
      }
      return {
        text: `Правок: ${updated.length}${paths.length > 1 ? ` в ${paths.length} проектах` : ''}. ${updated.map(line).join(' ')}`,
        structured: { path: lastSaved.path, rev: lastSaved.rev, updated, files: paths },
      };
    },

    async tasks_append(args = {}) {
      const block = String(args.block || '').trim();
      if (!block) throw new ToolError('invalid_block', 'Нужен текст блока.');
      const headingError = tasks.transcriptHeadingError(args.path, block);
      if (headingError) throw new ToolError('invalid_transcript_heading', headingError);
      const file = await readFile(args.path);
      // Стенограмма обязана лежать по времени, кем бы ни была записана: она
      // пишется несколькими сессиями сразу, и запись, начатая раньше, приходит
      // позже. tasks_checkpoint это делал (insertBlockByTime), а tasks_append —
      // нет, хотя заголовок стенограммы проверяет прямо выше и точно знает,
      // куда пишет. Итог на 04.09: 29 файлов из 35 лежали вразнобой, до 23
      // разрывов в дне. Порядок — свойство файла, а не следствие того, каким
      // путём блок пришёл.
      const chrono = tasks.isTranscriptCorpusPath(args.path);
      const put = (text) => (chrono ? tasks.insertBlockByTime(text, block) : tasks.appendBlock(text, block));
      const saved = await writeFile(file, put(file.text), { rebase: put, delta: { mode: chrono ? 'chrono' : 'append', block } });
      return {
        text: `Дописал в ${saved.path} (${block.split('\n').length} строк).`,
        structured: { path: saved.path, rev: saved.rev, lines: block.split('\n').length },
      };
    },

    async tasks_checkpoint(args = {}) {
      const transcriptBlock = String(args.transcript_block || '').trim();
      if (!transcriptBlock) throw new ToolError('invalid_transcript', 'Нужен полный блок стенограммы текущего обмена.');
      // date — для записи задним числом. Без него путь всегда «сегодня» по МСК,
      // и обмен про вчерашний вечер молча ложится в сегодняшний transcript/
      // (инцидент 06.08: блоки 23:40/23:55 про 05.08 оказались в 2026-08-06.md).
      const day = checkpointDay(args.date);
      const transcriptPath = tasks.transcriptPath(day);
      const headingError = tasks.transcriptHeadingError(transcriptPath, transcriptBlock);
      if (headingError) throw new ToolError('invalid_transcript_heading', headingError);
      if (!/^\*\*Кин:\*\*/m.test(transcriptBlock) || !/^\*\*Claude:\*\*/m.test(transcriptBlock)) {
        throw new ToolError(
          'incomplete_transcript_exchange',
          'Checkpoint не принят: в стенограмме нужны обе стороны — «**Кин:**» и «**Claude:**». Без одной из них это не полный обмен.',
        );
      }
      const verbatimError = tasks.verbatimTranscriptError(transcriptBlock);
      if (verbatimError) throw new ToolError('verbatim_transcript_required', verbatimError);

      const journalBlock = String(args.journal_block || '').trim();
      const journalPath = `journal/${day.slice(0, 7)}.md`;
      if (journalBlock) {
        const expected = new RegExp(`^##\\s+${day.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&')}\\s+\\d{1,2}:\\d{2}\\s+·\\s+.+$`, 'm');
        if (!expected.test(journalBlock)) {
          throw new ToolError(
            'invalid_journal_heading',
            `Запись журнала должна начинаться «## ${day} ЧЧ:ММ · тема». Стенограмму ещё не писал: исправь блок и повтори checkpoint целиком.`,
          );
        }
      }

      // Оба блока валидируем до первой записи: ошибка формата не должна
      // оставить половину checkpoint. Сетевой сбой между двумя файлами всё
      // ещё возможен, поэтому в ответе возвращаются отдельные ревизии.
      // Метка вызова дописывается после всех проверок формата: они должны
      // видеть блок ровно таким, каким его прислала модель. Сама модель
      // `session_id` не знает и знать не должна — его выдаёт сервер, поэтому
      // строку добавляет тоже сервер (MCP_TELEMETRY_ROADMAP.md, фаза 2).
      const mark = callContext.transcriptMark(callContext.current());
      const blockToWrite = mark ? `${transcriptBlock}\n${mark}` : transcriptBlock;

      // По времени, а не в конец: стенограмму пишут несколько сессий сразу, и
      // запись, начатая раньше, приходит позже — хронология рвалась прямо в
      // файле (20:10, следом 14:20, следом 18:45). Режим дельты совпадает с
      // тем, что делает put, иначе rebase и серверная дельта разойдутся.
      const transcript = await openForAppend(transcriptPath);
      const putTranscript = (text) => tasks.insertBlockByTime(text, blockToWrite);
      const savedTranscript = await writeFile(transcript, putTranscript(transcript.text), {
        rebase: putTranscript,
        delta: { mode: 'chrono', block: blockToWrite },
      });

      let savedJournal = null;
      if (journalBlock) {
        const journal = await openForAppend(journalPath);
        const putJournal = (text) => tasks.appendBlock(text, journalBlock);
        savedJournal = await writeFile(journal, putJournal(journal.text), {
          rebase: putJournal,
          delta: { mode: 'append', block: journalBlock },
        });
      }

      try {
        const state = await loadState();
        if (state.transcript_pending) await writeState(tasks.clearTranscriptPending(state));
      } catch {
        // pending — страховка для хуков/приписки; сбой очистки не откатывает checkpoint
      }

      const reminders = tasks.checkpointOutputReminders({ transcriptBlock, journalBlock });
      let text = `Обмен сохранён: стенограмма ${transcriptPath}${savedJournal ? `, вывод — ${journalPath}` : '; устойчивого вывода для журнала нет'}.`;
      const structured = {
        checkpoint: true,
        date: day,
        transcript_pending: false,
        transcript: { path: savedTranscript.path, rev: savedTranscript.rev },
        journal: savedJournal ? { path: savedJournal.path, rev: savedJournal.rev } : null,
      };
      if (reminders.journal_reminder) {
        text += `\n\n${reminders.journal_reminder}`;
        structured.journal_reminder = reminders.journal_reminder;
      }
      if (reminders.fact_reminder) {
        text += `\n\n${reminders.fact_reminder}`;
        structured.fact_reminder = reminders.fact_reminder;
      }
      if (reminders.board_reminder) {
        text += `\n\n${reminders.board_reminder}`;
        structured.board_reminder = reminders.board_reminder;
      }

      return { text, structured };
    },

    /**
     * Единственная операция, которая переписывает кусок файла. Ревизия здесь
     * обязательна: без неё переработка раздела превращается в ту самую
     * целиковую запись, ради отказа от которой всё и затевалось.
     */
    async tasks_patch(args = {}) {
      const file = await readFile(args.path);
      const rev = Number(args.rev);
      if (!Number.isInteger(rev)) throw new ToolError('invalid_rev', 'Нужна ревизия файла из tasks_read.');
      if (rev !== file.rev) {
        throw new ToolError(
          'stale_rev',
          `Файл ${file.path} изменился с момента чтения (была ревизия ${rev}, сейчас ${file.rev}). Перечитай его и повтори правку — иначе затрёшь чужое.`,
          { path: file.path, current_rev: file.rev },
        );
      }
      let nextText;
      try {
        nextText = tasks.patchBlock(file.text, { from: args.from, to: args.to || null, replacement: args.replacement });
      } catch (e) {
        const msg = String(e && e.message || e);
        if (msg.startsWith('anchor_ambiguous:')) {
          throw new ToolError(
            'anchor_ambiguous',
            `Якорь неоднозначен: ${msg}. Уточни from/to более длинным куском строки.`,
          );
        }
        throw new ToolError('anchor_not_found', `Якорь не найден: ${msg}. Перечитай файл и возьми точную строку или уникальный кусок.`);
      }
      const saved = await writeFile(file, nextText);
      return {
        text: `Заменил блок в ${saved.path} (ревизия ${saved.rev}).`,
        structured: { path: saved.path, rev: saved.rev },
      };
    },
  });

  /** Задача по хэшу: общий вход для инструментов, которые её правят. */
  async function locateTask(project, hash) {
    const key = String(project || '').toLowerCase().replace(/\.md$/i, '');
    if (!key) throw new ToolError('invalid_project', 'Нужен проект задачи.');
    if (!hash) throw new ToolError('invalid_hash', 'Нужен хэш задачи с доски.');
    const file = await readFile(`projects/${key}.md`);
    const found = tasks.findTaskByHash(file, hash);
    if (!found) {
      throw new ToolError('task_not_found', `В ${file.path} нет задачи с хэшем ${hash}. Возьми актуальный через tasks_list.`);
    }
    return { file, found, key };
  }

  // Дата по Москве, а не по UTC: задачник живёт по МСК, и с полуночи до трёх
  // ночи «сегодня» по серверу — это ещё вчера по его календарю.
  function today() {
    return tasks.taskDay(nowMs);
  }

  /**
   * Какой день закрываем. Пусто — вчерашний: закрытие живёт на утренней
   * планёрке, а вечером день ещё не кончился. Слова понимаются наравне с
   * датой — куратор говорит «закрой вчера», а не «закрой 2026-08-02».
   */
  const CLOSE_DAY_WORDS = {
    'вчера': -1, 'вчерашний': -1, 'вчерашний день': -1, 'yesterday': -1,
    'сегодня': 0, 'сегодняшний': 0, 'сегодняшний день': 0, 'today': 0,
    'позавчера': -2, 'позавчерашний': -2,
  };

  function closeDayDate(raw) {
    const text = String(raw ?? '').trim().toLowerCase();
    if (!text) return tasks.shiftDate(today(), -1);
    if (Object.prototype.hasOwnProperty.call(CLOSE_DAY_WORDS, text)) {
      return tasks.shiftDate(today(), CLOSE_DAY_WORDS[text]);
    }
    return String(raw).trim();
  }

  /**
   * День файла стенограммы / дата шапки журнала для checkpoint.
   * Пусто — сегодня. Слова «вчера»/«позавчера» и ISO — для записи задним
   * числом. Будущее отклоняем: иначе ночной обмен уедет в ещё не наступивший
   * день и ревизия хвоста его не увидит.
   */
  function checkpointDay(raw) {
    if (raw == null || String(raw).trim() === '') return today();
    const text = String(raw).trim().toLowerCase();
    let day;
    if (Object.prototype.hasOwnProperty.call(CLOSE_DAY_WORDS, text)) {
      day = tasks.shiftDate(today(), CLOSE_DAY_WORDS[text]);
    } else {
      day = String(raw).trim();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) {
        throw new ToolError(
          'invalid_checkpoint_date',
          `date — ISO ГГГГ-ММ-ДД или «вчера»/«сегодня»/«позавчера», а не «${raw}».`,
        );
      }
    }
    if (day > today()) {
      throw new ToolError(
        'future_transcript',
        `Стенограмму в будущее писать нельзя (asked ${day}, сегодня ${today()}).`,
      );
    }
    return day;
  }

  /**
   * Как адресуется слот, который надо снять или подвинуть.
   *
   * По времени начала, по словам заголовка или по обоим сразу. Одного времени
   * человеку мало («отмени праздник» — он не помнит, с которого часа), одних
   * слов тоже: «уборка» может стоять дважды. Поэтому принимаем и то и другое,
   * а строку вида «15:00 уборка» разбираем сами — модель всё равно перескажет
   * его слова как есть.
   */
  function splitSlotQuery(entry) {
    if (entry && typeof entry === 'object') return { at: entry.at || null, title: entry.title || null };
    const raw = String(entry || '').trim();
    const match = /^(\d{1,2}:\d{2})\s*(?:[-–—]\s*\d{1,2}:\d{2})?\s*(.*)$/.exec(raw);
    if (match) return { at: match[1], title: match[2].trim() || null };
    return { at: null, title: raw || null };
  }

  /**
   * Один слот дня по описанию — или внятный отказ.
   *
   * Молча взять первый подходящий нельзя: снятый не тот слот выглядит ровно
   * как выполненная просьба, и расхождение всплывёт через неделю. Поэтому при
   * нескольких совпадениях инструмент отказывается и перечисляет кандидатов —
   * уточнить время дешевле, чем чинить день задним числом.
   */
  function locateSlotIn(file, { at, title }, date) {
    const all = tasks.parseSlots(file.text);
    const listing = all.length
      ? all.map((s) => `${s.start}–${s.end} ${s.title}`).join('; ')
      : 'в этом дне вообще ничего не стоит';
    if (!at && !title) {
      throw new ToolError('slot_query_required', `Скажи, какой слот: время начала, слова из названия или и то и другое. В ${date}: ${listing}.`);
    }
    let found;
    try {
      found = tasks.findSlotsIn(file.text, { at, title });
    } catch (e) {
      throw new ToolError('invalid_time', `Время «${at}» не в формате ЧЧ:ММ.`);
    }
    if (!found.length) {
      throw new ToolError(
        'slot_not_found',
        `В ${date} нет слота «${[at, title].filter(Boolean).join(' ')}». Что там стоит: ${listing}.`,
        { date, slots: all.map((s) => ({ from: s.start, to: s.end, title: s.title })) },
      );
    }
    if (found.length > 1) {
      throw new ToolError(
        'slot_ambiguous',
        `Под «${[at, title].filter(Boolean).join(' ')}» в ${date} подходит ${found.length}: ${found.map((s) => `${s.start}–${s.end} ${s.title}`).join('; ')}. Спроси у него, какой именно, и передай время начала — сам я выбрать не могу.`,
        { date, candidates: found.map((s) => ({ from: s.start, to: s.end, title: s.title })) },
      );
    }
    return found[0];
  }

  async function locateSlot(date, args) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date))) {
      throw new ToolError('invalid_date', `Дата «${date}» не в формате ГГГГ-ММ-ДД.`);
    }
    const file = await readFile(`days/${date}.md`);
    const query = args.at || args.title
      ? { at: args.at || null, title: args.title || null }
      : splitSlotQuery(args.slot);
    return { file, slot: locateSlotIn(file, query, date) };
  }

  // Окно разбирается в одном месте на оба инструмента: разъехавшийся формат
  // здесь означал бы, что задача, заведённая захватом, и та же задача после
  // правки держат срок по-разному.
  function parseWindowArg(raw) {
    if (raw === undefined || raw === null || String(raw).trim() === '') return null;
    const value = String(raw).trim();
    const match = /^(\d{4}-\d{2}-\d{2})\s*\.\.\s*(\d{4}-\d{2}-\d{2})$/.exec(value);
    if (!match) {
      throw new ToolError('invalid_window', `Окно «${value}» не в формате ГГГГ-ММ-ДД..ГГГГ-ММ-ДД. «Начало недели» переведи в даты сам: он назвал срок словами, а границы считаешь ты.`);
    }
    if (match[1] > match[2]) {
      throw new ToolError('invalid_window', `В окне «${value}» начало позже конца.`);
    }
    return { from: match[1], to: match[2] };
  }

  function plural(n, one, few, many) {
    const mod100 = n % 100;
    if (mod100 >= 11 && mod100 <= 14) return many;
    const mod10 = n % 10;
    if (mod10 === 1) return one;
    if (mod10 >= 2 && mod10 <= 4) return few;
    return many;
  }

  // В пачке ошибку надо привязать к слоту, иначе «вид не из словаря» не говорит,
  // какой из шести переписывать.
  function slotWhere(i, batch) {
    return batch ? `Слот ${i + 1}: ` : '';
  }

  function insertLineAt(text, line, at) {
    const lines = String(text || '').split('\n');
    lines.splice(at, 0, line);
    return lines.join('\n').replace(/^\n+/, '');
  }

  /**
   * Один слот: проверить всё и собрать строку, ничего не записывая.
   *
   * `accText` — текст дня с уже подготовленными слотами этой пачки, поэтому
   * пересечения внутри неё считаются той же логикой, что и с уже стоящими:
   * второй слот видит первый, потому что тот уже в тексте.
   *
   * `projectFiles` — общий на вызов кэш прочитанных проектов: шесть слотов на
   * одну задачу читали бы её файл шесть раз.
   */
  async function prepareSlot(raw = {}, accText, projectFiles, i, batch) {
    const where = slotWhere(i, batch);
    const kind = raw.kind ? String(raw.kind).toLowerCase() : (raw.presence ? 'фон' : 'фокус');
    if (!tasks.SLOT_KINDS.has(kind)) {
      throw new ToolError('invalid_kind', `${where}вид «${raw.kind}» не из словаря доски: фон, дело, фокус, привычка.`);
    }
    // Время проверяется до slotConflicts намеренно: раньше любая ошибка оттуда
    // выходила наружу как «время не в формате ЧЧ:ММ», и настоящая причина
    // пряталась за чужим текстом.
    if (tasks.timeToMinutes(raw.from) === null || tasks.timeToMinutes(raw.to) === null) {
      throw new ToolError('invalid_time', `${where}время «${raw.from}–${raw.to}» не в формате ЧЧ:ММ.`);
    }
    const conflicts = tasks.slotConflicts(accText, raw.from, raw.to, kind);

    // Привязка слота к задаче пишется тем же видом, который доска читает
    // сама: «… · kinderly/8e3572». Свой формат здесь был бы двойником уже
    // работающего, и доска перестала бы делать слот кликабельным.
    let ref = null;
    if (raw.ref) {
      ref = tasks.parseAddress(raw.ref);
      if (!ref) throw new ToolError('invalid_ref', `${where}ссылка «${raw.ref}» не похожа на адрес с доски. Нужно «проект/хэш», например kinderly/8e3572.`);
      const path = `projects/${ref.project}.md`;
      if (!projectFiles.has(path)) projectFiles.set(path, await readFile(path));
      const refFile = projectFiles.get(path);
      if (!tasks.findTaskByHash(refFile, ref.hash)) {
        throw new ToolError('ref_not_found', `${where}в ${refFile.path} нет задачи ${ref.project}/${ref.hash}.`);
      }
    }
    // Чей слот и что он забирает — оба признака необязательны. Не сказал —
    // слот ничей и ничего не занимает, строка выходит ровно такой, какой была
    // до этой пары полей.
    const whose = raw.whose === undefined || raw.whose === null
      ? null
      : String(raw.whose).replace(/[()·;#@]/g, ' ').replace(/\s{2,}/g, ' ').trim();
    if (raw.whose !== undefined && raw.whose !== null && !whose) {
      throw new ToolError('invalid_whose', `${where}чей слот — одно имя словами: «жена», «Саша». Скобки, «·», «#» и «@» в него не помещаются: по ним разбирается сама строка.`);
    }
    const takesRaw = Array.isArray(raw.takes)
      ? raw.takes
      : (raw.takes === undefined || raw.takes === null || raw.takes === '' ? [] : [raw.takes]);
    const takes = [];
    for (const item of takesRaw) {
      const resource = tasks.normalizeResource(item);
      if (!resource || !tasks.SLOT_RESOURCES.has(resource)) {
        throw new ToolError(
          'invalid_resource',
          `${where}ресурс «${item}» не из словаря: машина, ребёнок. Общих ресурсов в семье ровно два — машина одна на двоих и ребёнок, который должен быть с кем-то. Третий не заводится словом в слоте.`,
        );
      }
      takes.push(resource);
    }
    const mark = tasks.buildSlotMark({ whose, takes });
    const refTail = ref ? ` · ${ref.project}/${ref.hash}` : '';
    // Тег пишется всегда, даже для «фокус» по умолчанию: без него доска
    // подставляет тот же смысл сама, но именно эта неявность и завела нас в
    // ложный конфликт — слот без тега и соседний слот без тега считались
    // «два дела требуют головы одновременно», хотя один из них был врезкой
    // на пятнадцать минут.
    // Скобка стоит до ссылки намеренно: доска ищет адрес задачи в хвосте
    // строки после последней «·», и признаки после него сделали бы слот
    // некликабельным.
    const title = String(raw.title).trim();
    const line = `- ${raw.from}–${raw.to} ${title}${mark ? ` ${mark}` : ''}${refTail} #${kind}`;
    return {
      line, kind, title, conflicts, whose, takes,
      from: raw.from, to: raw.to,
      presence: Boolean(raw.presence),
      ref: ref ? `${ref.project}/${ref.hash}` : null,
    };
  }

  Object.assign(tools, {
    async tasks_habit(args = {}) {
      const date = args.date || today();
      const file = await readFile('habits.md');
      let result;
      try {
        result = tasks.markHabit(file.text, args.habit, date);
      } catch (e) {
        throw new ToolError('habit_not_found', `Привычка «${args.habit}» не найдена в habits.md: ${e.message}`);
      }
      if (result.already) {
        return { text: `«${result.habit}» за ${date} уже отмечена.`, structured: { habit: result.habit, date, already: true } };
      }
      const saved = await writeFile(file, result.text);
      return {
        text: `Отметил «${result.habit}» за ${date}.`,
        structured: { habit: result.habit, date, already: false, rev: saved.rev },
      };
    },

    async tasks_slot(args = {}) {
      const date = args.date || today();
      // День расставляется целиком одним вызовом: описание дня приходит от него
      // фразой, а не по слоту за раз. Дата остаётся на уровне вызова намеренно —
      // с датой у каждого слота пачка перестала бы быть одной записью, и падение
      // на середине оставило бы половину дня расставленной (та же причина, по
      // которой tasks_close_day резолвит все галочки до записи).
      const batch = Array.isArray(args.slots) ? args.slots : null;
      if (batch && !batch.length) {
        throw new ToolError('empty_batch', 'В slots пустой список. Передай слоты или поставь один через from/to/title.');
      }
      const items = batch || [args];
      for (let i = 0; i < items.length; i += 1) {
        const item = items[i] || {};
        if (!item.from || !item.to || !String(item.title || '').trim()) {
          throw new ToolError(
            'slot_args_missing',
            `${slotWhere(i, batch)}нужны все три: from, to и title. Один слот ставится ими напрямую, несколько — списком slots.`,
          );
        }
      }

      const file = await readFile(`days/${date}.md`);
      const projectFiles = new Map();
      const addedRaw = new Set();
      const prepared = [];
      let accText = String(file.text || '');
      let presenceCount = 0;
      for (let i = 0; i < items.length; i += 1) {
        const slot = await prepareSlot(items[i], accText, projectFiles, i, batch);
        prepared.push(slot);
        addedRaw.add(slot.line.trim());
        // Крупные блоки присутствия идут выше слотов задач: доска рисует то, что
        // ниже в файле, поверх — иначе блок закроет собой всё, что внутри него.
        // Внутри пачки они складываются друг за другом, а не в обратном порядке.
        accText = slot.presence
          ? insertLineAt(accText, slot.line, presenceCount)
          : tasks.appendBlock(accText, slot.line);
        if (slot.presence) presenceCount += 1;
      }
      // Пересечение с тем, что уже стояло в дне, и пересечение с соседом по этой
      // же пачке — разные новости: во втором случае двигать надо то, что он
      // только что назвал, а не то, что стоит с утра.
      for (const slot of prepared) {
        for (const conflict of slot.conflicts) {
          conflict.with = addedRaw.has(conflict.raw) ? 'пачка' : 'день';
        }
      }

      // Запись ровно одна на весь вызов. Половина расставленного дня и ошибка на
      // третьем слоте — это день, про который непонятно, поставлен он или нет.
      const saved = await writeFile(file, accText);

      const conflicts = prepared.flatMap((slot) => slot.conflicts);
      const real = conflicts.filter((c) => c.level === 'конфликт');
      const soft = conflicts.filter((c) => c.level === 'вопрос');
      let warn = '';
      if (real.length) warn += ` Конфликт с: ${real.map((c) => c.title).join('; ')} — скажи об этом куратору.`;
      if (soft.length) warn += ` Стоит уточнить: ${soft.map((c) => c.title).join('; ')}.`;

      if (batch) {
        const listed = prepared.map((s) => `${s.from}–${s.to} ${s.title}`).join('; ');
        return {
          text: `Поставил на ${date} ${prepared.length} ${plural(prepared.length, 'слот', 'слота', 'слотов')}: ${listed}.${warn}`,
          structured: {
            date,
            count: prepared.length,
            slots: prepared.map((s) => ({
              from: s.from, to: s.to, title: s.title, kind: s.kind,
              whose: s.whose, takes: s.takes, ref: s.ref, conflicts: s.conflicts,
            })),
            conflicts,
            rev: saved.rev,
          },
        };
      }

      const one = prepared[0];
      // Занятость называется фактом, без вывода «значит туда не поедешь»:
      // что достижимо без машины и что делается с ребёнком, знает он один.
      const busy = one.takes.length
        ? ` В это время занято: ${one.takes.join(', ')}${one.whose ? ` (событие не его — ${one.whose})` : ''}.`
        : '';

      return {
        text: `Поставил на ${date}: ${one.from}–${one.to} ${one.title} (${one.kind}).${busy}${warn}`,
        structured: {
          date, from: one.from, to: one.to, title: one.title, kind: one.kind,
          whose: one.whose, takes: one.takes,
          ref: one.ref, conflicts, rev: saved.rev,
        },
      };
    },

    async tasks_unslot(args = {}) {
      const date = args.date || today();
      const { file, slot } = await locateSlot(date, args);
      const next = tasks.removeSlotLine(file.text, slot.line);
      const saved = await writeFile(file, next);
      // Слот и задача — разные вещи: «вытащил слот из календаря» значит снят с
      // плана, а не сделан или брошен. Задача остаётся там, где лежала, и
      // сказать об этом надо вслух, иначе следующий шаг будет «а куда делось».
      const link = tasks.parseSlotRef(slot.raw);
      const kept = link ? ` Задача ${link.ref.project}/${link.ref.hash} осталась на месте — снят только слот в дне.` : '';
      return {
        text: `Снял с ${date}: ${slot.start}–${slot.end} ${slot.title}.${kept}`,
        structured: {
          date, from: slot.start, to: slot.end, title: slot.title, kind: slot.kind,
          ref: link ? `${link.ref.project}/${link.ref.hash}` : null, rev: saved.rev,
        },
      };
    },

    async tasks_reslot(args = {}) {
      const date = args.date || today();
      const { file, slot } = await locateSlot(date, args);
      const toDate = args.to_date || date;
      if (!/^\d{4}-\d{2}-\d{2}$/.test(toDate)) {
        throw new ToolError('invalid_date', `Дата «${args.to_date}» не в формате ГГГГ-ММ-ДД.`);
      }

      // Длительность сохраняется сама: «перенеси на 16:00» — это про начало,
      // а не про то, что событие теперь длится до конца суток.
      const span = slot.to - slot.from;
      let from;
      let to;
      try {
        from = args.from ? tasks.padTime(args.from) : slot.start;
        to = args.to
          ? tasks.padTime(args.to)
          : (args.from ? tasks.minutesToTime(tasks.timeToMinutes(from) + span) : slot.end);
      } catch (e) {
        throw new ToolError('invalid_time', `Время «${args.from || ''}–${args.to || ''}» не в формате ЧЧ:ММ.`);
      }

      if (toDate === date && tasks.padTime(from) === tasks.padTime(slot.start) && tasks.padTime(to) === tasks.padTime(slot.end)) {
        return {
          text: `${slot.start}–${slot.end} ${slot.title} и так стоит на ${date} — не трогал.`,
          structured: { moved: false, date, from: slot.start, to: slot.end, title: slot.title, conflicts: [] },
        };
      }

      // Пересечения считаются на новом месте той же логикой, что и постановка,
      // и обязательно БЕЗ самого переносимого слота: иначе он найдёт конфликт
      // сам с собой и остановит перенос на пустом месте.
      const sourceWithout = tasks.removeSlotLine(file.text, slot.line);
      const targetFile = toDate === date ? null : await readFile(`days/${toDate}.md`);
      const targetText = toDate === date ? sourceWithout : (targetFile.text || '');
      let conflicts;
      try {
        conflicts = tasks.slotConflicts(targetText, from, to, slot.kind);
      } catch (e) {
        throw new ToolError('invalid_time', `Время «${from}–${to}» не в формате ЧЧ:ММ.`);
      }

      let rev;
      if (toDate === date) {
        const saved = await writeFile(file, tasks.retimeSlotLine(file.text, slot.line, from, to));
        rev = saved.rev;
      } else {
        // Сначала пишем туда, потом убираем отсюда. Порядок не косметический:
        // упади вторая запись — слот окажется в двух днях, и это видно и
        // чинится; упади первая при обратном порядке — он исчезнет молча.
        const parts = tasks.splitSlotLine(slot.raw);
        const line = tasks.buildSlotLine({ ...parts, from, to });
        const nextTarget = slot.kind === 'фон'
          ? [line, ...String(targetFile.text || '').split('\n')].join('\n').replace(/^\n+/, '')
          : tasks.appendBlock(targetFile.text, line);
        const saved = await writeFile(targetFile, nextTarget);
        rev = saved.rev;
        await writeFile(file, sourceWithout);
      }

      const real = conflicts.filter((c) => c.level === 'конфликт');
      const soft = conflicts.filter((c) => c.level === 'вопрос');
      let warn = '';
      if (real.length) warn += ` Конфликт с: ${real.map((c) => c.title).join('; ')} — скажи об этом куратору.`;
      if (soft.length) warn += ` Стоит уточнить: ${soft.map((c) => c.title).join('; ')}.`;

      return {
        text: `Перенёс: ${slot.title} — было ${date} ${slot.start}–${slot.end}, стало ${toDate} ${from}–${to}.${warn}`,
        structured: {
          moved: true, date, to_date: toDate, from, to, title: slot.title, kind: slot.kind,
          was: { date, from: slot.start, to: slot.end }, conflicts, rev,
        },
      };
    },

    /**
     * Закрытие дня. Без него вся ретроспектива слепая: в файлах остаётся один
     * план, и «как прошла неделя», «что я забросил», «сколько реально ушло на
     * kinderly» отвечать нечем — слот без галочки в незакрытом дне значит
     * «неизвестно», а не «не состоялось».
     *
     * Формат не наш: галочка `- [x]` и строка `> …` внизу — это то, что уже
     * описано в days/README.md и что рисует доска.
     *
     * Дата по умолчанию — вчерашняя, а не сегодняшняя. Решение владельца от
     * 2026-08-03: день закрывают утром, когда он уже кончился; вечером
     * закрывать нечего, а «сегодня» по умолчанию раз за разом закрывало не тот
     * день. Сегодняшний закрывается явно — датой или словом «сегодня».
     */
    /**
     * Отметка по ходу дня. Отдельно от закрытия дня — и это главное в ней.
     *
     * Раньше галочку умел ставить только tasks_close_day, а он обязан писать
     * заметку «> как прошло», по которой доска и считает день закрытым
     * (build_board.day_closed). Отметить дело в обед было нельзя, не объявив
     * день законченным: 3 сентября так одиннадцать ещё не наступивших пунктов
     * стали читаться как «не состоялись».
     *
     * Пишем ровно то же, что доска: галочку и событие «~ ЧЧ:ММ закрыт · …».
     * Из этих строк вечером собирается «План и факт», поэтому чат, ставящий
     * галочку молча, оставил бы вечер без половины фактов.
     */
    async tasks_slot_done(args = {}) {
      const date = args.date ? closeDayDate(args.date) : today();
      const query = String(args.slot || '').trim();
      if (!query) {
        throw new ToolError('slot_required', 'Скажи, какой слот отмечаем: время, название или то и другое.');
      }
      const at = String(args.at || '').trim();
      if (at && !/^\d{1,2}:\d{2}$/.test(at)) {
        throw new ToolError('bad_time', `Время закрытия пишется ЧЧ:ММ, а пришло «${at}».`);
      }

      const file = await readFile(`days/${date}.md`);
      const { at: queryAt, title } = splitSlotQuery(query);
      const slot = locateSlotIn(file, { at: queryAt, title }, date);

      // Уже отмеченный слот — не ошибка: он мог сказать дважды или отметить
      // на доске. Молчим и не трогаем время в событии: оно про первый раз.
      if (slot.done) {
        return {
          text: `Уже отмечено: ${slot.start} ${slot.title}.`,
          structured: { date, slot: { from: slot.start, to: slot.end, title: slot.title }, already: true },
        };
      }

      let text = tasks.markSlotDone(file.text, slot.line, true);
      if (!tasks.hasDayEvent(text, 'закрыт', slot)) {
        text = tasks.appendDayEvent(text, 'закрыт', slot, { at: at || null, nowMs });
      }
      const saved = await writeFile(file, text);

      const rest = tasks.parseSlots(text).filter((s) => !s.done);
      const closed = tasks.dayNote(text);
      const tail = rest.length
        ? ` Осталось ${rest.length}: ${rest.slice(0, 3).map((s) => `${s.start} ${s.title}`).join(', ')}${rest.length > 3 ? '…' : ''}`
        : ' Это было последнее на сегодня.';

      return {
        text: `Отметил: ${slot.start} ${slot.title}.${tail}`
          + (closed ? '' : ' День не закрываю — закрытие вечером, одной фразой «как прошло».'),
        structured: {
          date,
          rev: saved.rev,
          slot: { from: slot.start, to: slot.end, title: slot.title },
          open: rest.map((s) => ({ from: s.start, to: s.end, title: s.title })),
          dayClosed: Boolean(closed),
        },
      };
    },
    async tasks_close_day(args = {}) {
      const date = closeDayDate(args.date);
      const note = String(args.note || '').trim();
      if (!note) {
        throw new ToolError(
          'note_required',
          'Нужна одна фраза «как прошло» — она же отметка того, что день закрывали. Без неё слот без галочки не отличить от «ещё не смотрели».',
        );
      }
      const file = await readFile(`days/${date}.md`);
      const before = tasks.dayNote(file.text);

      // Сначала находим всё, потом пишем: половина отмеченных галочек и
      // ошибка на третьей — это день, про который непонятно, закрыт он или нет.
      const asked = Array.isArray(args.done) ? args.done : (args.done ? [args.done] : []);
      const picked = [];
      for (const entry of asked) {
        const { at, title } = splitSlotQuery(entry);
        const slot = locateSlotIn(file, { at, title }, date);
        // Один слот, названный дважды («10:00» и «лендинг»), — это один слот,
        // а не два состоявшихся дела: иначе «состоялось 3 из 2».
        if (!picked.some((s) => s.line === slot.line)) picked.push(slot);
      }

      let text = file.text;
      const marked = [];
      for (const slot of picked) {
        if (slot.done) { marked.push({ ...slot, already: true }); continue; }
        text = tasks.markSlotDone(text, slot.line, true);
        // Событие «~ … закрыт · …» — то же, что пишет доска: из него вечером
        // собирается «План и факт». Галочка без него оставляет разбор без
        // времени, а закрытие дня — ровно тот момент, когда его читают.
        if (!tasks.hasDayEvent(text, 'закрыт', slot)) {
          text = tasks.appendDayEvent(text, 'закрыт', slot, { nowMs });
        }
        marked.push({ ...slot, already: false });
      }
      text = tasks.setDayNote(text, note);
      const saved = await writeFile(file, text);

      const doneLines = new Set(marked.map((s) => s.line));
      const open = tasks.parseSlots(text)
        .filter((slot) => !slot.done && !doneLines.has(slot.line))
        .map((slot) => ({ from: slot.start, to: slot.end, title: slot.title, kind: slot.kind }));

      const tail = open.length
        ? ` Без отметки осталось ${open.length}: ${open.map((s) => `${s.from} ${s.title}`).join('; ')} — перенести (tasks_reslot), снять (tasks_unslot) или оставить как есть, решает он.`
        : '';

      // Деньги спрашиваются только по завершённому дню. Закрывают обычно
      // вчерашний — там и спрашиваем; закрытие сегодняшнего (это делается
      // явно) деньгами не трогаем: день ещё идёт, и «операций нет» соврёт.
      const money = date < today() ? await moneyDayNudge(date) : null;

      return {
        text: `${before ? 'Переписал закрытие' : 'Закрыл день'} ${date}: состоялось ${marked.length} из ${marked.length + open.length}. Заметка: «${note}».${tail}`
          + (money ? `\n\n${money.reminder}` : ''),
        structured: {
          date, note, rev: saved.rev,
          money_reminder: money ? money.reminder : null,
          money_day: money ? money.status : null,
          already_closed: !!before,
          previous_note: before ? before.text : null,
          done: marked.map((s) => ({ from: s.start, to: s.end, title: s.title, already: s.already })),
          open,
        },
      };
    },

    async tasks_money(args = {}) {
      const contour = String(args.contour || '').trim();
      if (!contour) throw new ToolError('contour_required', 'У операции обязателен контур — без него она не попадёт в разбивку на доске.');
      const amount = Number(args.amount);
      if (!Number.isFinite(amount) || amount === 0) throw new ToolError('invalid_amount', 'Сумма должна быть числом и не нулём.');
      const date = args.date || today();
      const month = date.slice(0, 7);

      const category = String(args.category || '').trim().replace(/\s+/g, '-');
      if (!category) {
        throw new ToolError(
          'category_required',
          'Нужна категория, как в Zenmoney: продукты, связь, зарплаты, инструменты, кредит. Без неё строка не попадёт в разбивку по категориям на доске.',
        );
      }

      const file = await readFile(`money/${month}.md`);
      const line = tasks.moneyLine({
        date, amount, income: !!args.income, category, contour,
        account: args.account ? String(args.account).trim() : null,
        comment: args.title ? String(args.title).trim() : null,
      });
      const put = (text) => tasks.prependToSection(text, line, '## Операции');
      const saved = await writeFile(file, put(file.text), { rebase: put });

      // Картина месяца после записи — тот же смысл, что у day_after в
      // дневниках: не «записал», а «вот что теперь». Оценок не даём: лимиты в
      // budget.md стоят «?» по его решению не выдумывать нормы раньше времени.
      let recurring = null;
      try {
        recurring = (await readFile('money/recurring.md')).text;
      } catch (_) { /* нет файла регулярных — прогноз просто не покажем */ }
      const month_after = tasks.monthAfter(saved.text, { month, today: date, contour, recurring });

      const sign = args.income ? '+' : '-';
      const picture = [
        `в ${contour} за месяц ${month_after.contour.spent} ₽`,
        `всего расходов ${month_after.spent} ₽`,
        month_after.today_spent ? `сегодня ${month_after.today_spent} ₽` : null,
        month_after.balance ? `остаток на ${month_after.balance.date} — ${month_after.balance.amount} ₽` : null,
        month_after.recurring_ahead ? `до конца месяца спишется само ещё ~${month_after.recurring_ahead} ₽` : null,
      ].filter(Boolean).join(', ');

      return {
        text: `Записал: ${sign}${Math.abs(amount)} ₽ · ${category} · ~${contour}. Теперь ${picture}.`,
        structured: {
          date, amount, income: !!args.income, category, contour,
          account: args.account || null, comment: args.title || null,
          path: saved.path, rev: saved.rev, month_after,
        },
      };
    },

    async tasks_subtask(args = {}) {
      const { file, found, key } = await locateTask(args.project, args.hash);
      let result;
      try {
        result = tasks.toggleSubtask(file.text, found.line, args.subtask, args.done !== false);
      } catch (e) {
        throw new ToolError('subtask_not_found', `У задачи нет подпункта «${args.subtask}». Посмотри её через tasks_read.`);
      }
      const saved = await writeFile(file, result.text);
      return {
        text: `${key}/${args.hash} · ${found.parsed.title}: подпункт «${result.matched}» ${args.done === false ? 'снят' : 'отмечен'}.`,
        structured: { path: saved.path, rev: saved.rev, hash: args.hash, subtask: result.matched, done: args.done !== false },
      };
    },

    async tasks_resolve(args = {}) {
      const { file, found, key } = await locateTask(args.project, args.hash);
      let result;
      try {
        result = tasks.removeChild(file.text, found.line, args.needle);
      } catch (e) {
        throw new ToolError('child_not_found', `У задачи нет строки со словами «${args.needle}».`);
      }
      let nextText = args.note ? tasks.appendChild(result.text, found.line, String(args.note).trim()) : result.text;

      // Сняли последний «открыто:» — задача больше не ждёт решения, и тег
      // #blocked обязан уйти вместе с ним. Иначе блок «Требует решения»
      // копит уже решённое, перестаёт быть коротким и его перестают читать.
      const lines = nextText.split('\n');
      const stillOpen = tasks.parseTasks({ path: file.path, text: nextText })
        .find((t) => t.line - 1 === found.line)?.children
        .some((c) => /^открыто:/i.test(c));
      let unblocked = false;
      if (!stillOpen && /#blocked\b/.test(lines[found.line])) {
        lines[found.line] = tasks.applyTaskPatch(lines[found.line], { removeTags: ['blocked'] });
        nextText = lines.join('\n');
        unblocked = true;
      }

      const saved = await writeFile(file, nextText);

      // Исход находки: до сих пор нигде не оставалось следа, что человек
      // ответил. Без этого нельзя отличить полезный обход от генератора шума —
      // и нечем оправдать ни один порог. Пишем ответ туда же, где лежит
      // предложение, по ссылке на задачу.
      let remembered = null;
      if (unblocked) {
        const state = await loadState();
        const ref = `${key}/${args.hash}`;
        const entry = Object.entries(state.proposals).find(([, p]) => p && p.ref === ref && tasks.PROPOSAL_OPEN_STATUSES.has(p.status));
        if (entry) {
          const next = tasks.answerProposal(state, entry[0], {
            status: 'accepted', nowMs, note: args.note ? String(args.note).trim() : result.removed,
          });
          if (next) { await writeState(next); remembered = entry[0]; }
        }
      }

      /**
       * Ответ, который оказался фактом о его мире, а не решением по этой задаче.
       *
       * Без этого он не оседал нигде: строка ложится ДОЧЕРНЕЙ под задачу, задачу
       * закрывают, и вместе с ней в архив уезжает «склад 200 м²» — а через
       * неделю его спрашивают снова. Отдельный аргумент, а не догадка по тексту:
       * отличить факт о мире от решения по задаче кодом нельзя, а угадывать тут
       * — значит засорять память ответами вида «да, переносим на четверг».
       *
       * Пишется тем же путём, что и tasks_learn: та же проверка на повтор, та же
       * обязательная опора. Опора здесь заведомо есть — это его ответ на
       * конкретный вопрос конкретной задачи, и он подставляется сам.
       */
      let learned = null;
      let learnFailed = null;
      const fact = String(args.fact || '').trim();
      if (fact) {
        // Вопрос уже снят и файл записан. Отказ памяти (то же уже записано
        // другим значением, строку правят из другой сессии) не имеет права
        // превратить это в ошибку всего вызова: тогда модель повторит
        // tasks_resolve, а снимать уже нечего. Говорим об отказе словами.
        try {
          learned = await tools.tasks_learn({
            note: fact,
            kind: 'факт',
            evidence: `его ответ на «${result.removed}» — ${key}/${args.hash}, ${today()}`,
            question: result.removed.replace(/^открыто:\s*/i, '').trim() || null,
            // Ответ на вопрос сплошь и рядом не добавляет факт, а исправляет
            // прежний. Без проброса память откажет по дублю, и путь через
            // resolve оказался бы годен только для первого раза.
            replaces: String(args.fact_replaces || '').trim() || null,
          });
        } catch (e) {
          learnFailed = e && e.message ? e.message : 'память не приняла запись';
        }
      }

      // Напоминание там, куда модель точно смотрит, — в результате её же
      // вызова. Принудить её кодом нельзя: вопрос звучит в чате, коннектор его
      // не видит. Приписка идёт только когда ответ записан и фактом не назван:
      // на пустом снятии строки напоминать не о чем, а приписка на каждый вызов
      // перестаёт читаться первой.
      const nudge = args.note && !fact
        ? ' Если его ответ — факт о его мире (не решение по этой задаче), он уедет в архив вместе с задачей: передай его в fact, чтобы он лёг в память.'
        : '';

      return {
        text: `${key}/${args.hash} · ${found.parsed.title}: снял «${result.removed}»${args.note ? ', записал ответ' : ''}${unblocked ? '. Открытых вопросов больше нет — убрал из «Требует решения»' : ''}.`
          + `${learned ? ` В память: ${learned.text}` : ''}${learnFailed ? ` В память НЕ легло: ${learnFailed}` : ''}${nudge}`,
        structured: {
          path: saved.path, rev: saved.rev, hash: args.hash, removed: result.removed,
          note: args.note || null, unblocked, remembered,
          fact: fact || null, learned: learned ? learned.structured : null,
          learn_failed: learnFailed,
        },
      };
    },

    /**
     * Развилка на доску. Ничего нового в формате не изобретаем: доска уже
     * собирает блок «Требует решения» из задач с тегом #blocked, а панель
     * «Открыто» — из вложенных строк «открыто:». Инструмент просто пишет
     * развилку в этом виде, поэтому она видна там, где куратор её и ищет.
     *
     * Почему это нужно отдельным инструментом: вопрос, заданный в переписке,
     * живёт до конца разговора. Куратор закрывает чат, вопрос исчезает, а
     * решение так и не принято — и следующий проход начинается с того же
     * вопроса. На доске он лежит, пока на него не ответят.
     */
    async tasks_decision(args = {}) {
      const questions = (Array.isArray(args.questions) ? args.questions : [])
        .map((q) => String(q).trim())
        .filter(Boolean);
      if (!questions.length) throw new ToolError('questions_required', 'Нужен хотя бы один вопрос, ответ на который меняет твои дальнейшие действия.');

      const context = (Array.isArray(args.context) ? args.context : [])
        .map((c) => String(c).trim())
        .filter(Boolean);

      // Сначала смотрим, что уже висит открытым. Дубль вопроса, уже записанный
      // факт и переполненная доска — три причины не писать; все дешевле поймать
      // до записи. Память читается отдельным чтением: в проекты она не входит,
      // а один лишний ключ на развилку — цена не та, чтобы её считать.
      const openIndex = await loadIndex();
      const openFiles = await readAll({ paths: projectPaths(openIndex) });
      const openQuestions = tasks.collectOpenQuestions(openFiles);
      let facts = [];
      try { facts = tasks.parsePreferences(await readFile(tasks.PREFS_PATH)); } catch (_) { /* нет памяти — просто нечем сверять */ }
      const guard = tasks.decisionGuard(openQuestions, questions, { facts });

      // Вопрос, ответ на который уже записан фактом, на доску не кладётся вовсе.
      // Это тот же четвёртый вопрос про марку машины, только он переживёт
      // разговор и будет ждать ответа, который давно дан.
      if (guard.answered.length && !guard.fresh.length) {
        const known = guard.answered
          .map((a) => `${a.fact.date} · ${a.fact.note}${a.fact.evidence ? ` — ${a.fact.evidence}` : ''}`)
          .join('; ');
        return {
          text: `Не стал класть на доску: ответ уже записан в памяти — ${known}. Если он устарел, обнови его через tasks_learn с replaces, а не спрашивай заново.`,
          structured: { created: false, reason: 'known', answered: guard.answered, duplicates: guard.duplicates, open_count: guard.open_count },
        };
      }

      if (!guard.fresh.length) {
        const where = [...new Set(guard.duplicates.map((d) => d.ref).filter(Boolean))].join(', ');
        return {
          text: `Не стал дублировать: такой вопрос уже открыт${where ? ` — ${where}` : ''}. Ответа на него всё ещё нет.`,
          structured: { created: false, reason: 'duplicate', duplicates: guard.duplicates, open_count: guard.open_count },
        };
      }

      // Развилка по существующей задаче вешается на неё: вторая задача про то
      // же самое разводит контекст по двум местам, и отвечать приходится дважды.
      if (args.hash) {
        const { file, found, key } = await locateTask(args.project, args.hash);
        const lines = file.text.split('\n');
        const blocked = /#blocked\b/.test(lines[found.line])
          ? lines[found.line]
          : tasks.applyTaskPatch(lines[found.line], { addTags: ['blocked'] });
        let nextText = [...lines.slice(0, found.line), blocked, ...lines.slice(found.line + 1)].join('\n');
        for (const line of [...context, ...guard.fresh.map((q) => `открыто: ${q}`)]) {
          nextText = tasks.appendChild(nextText, found.line, line);
        }
        const saved = await writeFile(file, nextText);
        const skipped = guard.duplicates.length ? `, ${guard.duplicates.length} уже были открыты` : '';
        const answered = guard.answered.length ? `, ${guard.answered.length} снял — ответ уже в памяти` : '';
        return {
          text: `${key}/${args.hash} · ${found.parsed.title}: развилка на доске, вопросов ${guard.fresh.length}${skipped}${answered}.`,
          structured: {
            path: saved.path, rev: saved.rev, hash: args.hash, title: found.parsed.title,
            questions: guard.fresh, duplicates: guard.duplicates, answered: guard.answered,
            attached: true, created: true,
          },
        };
      }

      // Потолок — OPEN_DECISIONS_CAP, сейчас тридцать. Доска, на которой уже
      // висит тридцать нерешённых развилок, не станет полезнее от тридцать первой —
      // её просто не прочитают вместе с остальными. Это отказ, а не
      // предупреждение: предупреждение агент проигнорирует.
      // Привязка к существующей задаче (выше) под потолок не попадает намеренно
      // и обходом не является: она не добавляет новую строку в «Требует
      // решения», вопрос ложится под ту задачу, которая уже там висит.
      if (guard.over_cap) {
        throw new ToolError(
          'too_many_open_decisions',
          `На доске уже ${guard.open_count} нерешённых развилок (потолок ${guard.cap}): ${guard.open_refs.join(', ')}. `
          + 'Новую не завожу. Либо привяжи вопрос к одной из них через hash, либо скажи куратору, что сначала нужно закрыть висящее.',
        );
      }

      const project = String(args.project || '').toLowerCase().replace(/\.md$/i, '');
      if (!project) throw new ToolError('invalid_project', 'Нужен проект развилки.');
      const title = String(args.title || '').trim();
      if (!title) throw new ToolError('invalid_title', 'Нужно, что именно решить — одной строкой, глаголом.');

      const file = await readFile(`projects/${project}.md`);
      const today_ = today();
      // P2, а не P1: развилка ждёт ответа, но внешнего срока у неё нет. P1 без
      // названной даты или последствия пропуска ставит её в один ряд с
      // настоящей срочностью, и тогда «Требует решения» начинает соревноваться
      // с просрочкой — а читать перестают оба списка.
      const line = `- [ ] P2 ${title} #blocked ^${today_}`;
      let nextText = tasks.appendToSection(file.text, line, '## Задачи');

      // Строку задачи ищем после вставки: appendToSection кладёт её в конец
      // своего раздела, а не файла, поэтому номер строки заранее не известен.
      const taskLine = nextText.split('\n').findIndex((l) => l === line);
      for (const child of [...context, ...guard.fresh.map((q) => `открыто: ${q}`)]) {
        nextText = tasks.appendChild(nextText, taskLine, child);
      }
      const saved = await writeFile(file, nextText);

      const hash = tasks.taskHash(project, tasks.taskTitle(line));
      // Развилка, выросшая из находки обхода, записывается в память прохода:
      // иначе обзор через две недели поднимет то же самое второй задачей —
      // одна память будет молчать, другая повторяться.
      if (args.key) {
        const state = await loadState();
        await writeState(tasks.rememberProposal(
          state,
          { key: String(args.key), kind: 'decision', subject: title, title, project },
          { nowMs, ref: `${project}/${hash}` },
        ));
      }
      const skipped = guard.duplicates.length ? ` ${guard.duplicates.length} вопрос(а) уже были открыты — не повторял.` : '';
      const answered = guard.answered.length
        ? ` ${guard.answered.length} не положил — ответ уже записан в памяти: ${guard.answered.map((a) => a.fact.note).join('; ')}.`
        : '';
      return {
        text: `Положил на доску: ${title}. Вопросов: ${guard.fresh.length}. Ссылка: ${project}/${hash}.${skipped}${answered}`,
        structured: {
          path: saved.path, rev: saved.rev, hash, title, created: true,
          questions: guard.fresh, duplicates: guard.duplicates, answered: guard.answered,
          context, attached: false,
          open_count: guard.open_count + 1, cap: guard.cap,
        },
      };
    },

    /**
     * Память о том, как он решает. Не скрытое состояние, а обычный файл
     * задачника: он должен уметь прочитать это глазами и вычеркнуть неверное.
     * Записывается только подтверждённое — его слова, его выбор.
     */
    /** Голос эксперимента «два ответа». Копится обычным файлом задачника. */
    async tasks_vote(args = {}) {
      const choice = String(args.choice || '').trim();
      if (!['1', '2', 'ничья'].includes(choice)) {
        throw new ToolError('invalid_choice', 'Выбор — «1», «2» или «ничья».');
      }
      const procedural = String(args.procedural || '').trim();
      if (!['1', '2'].includes(procedural)) {
        throw new ToolError('invalid_procedural', 'Нужен номер процедурного ответа: «1» или «2».');
      }
      const question = String(args.question || '').trim();
      if (!question) throw new ToolError('invalid_question', 'Нужна суть вопроса одной строкой.');

      const file = await readFile(tasks.VOTES_PATH);
      const winner = tasks.voteWinner(choice, procedural);
      const line = tasks.voteLine({
        date: today(), winner, question,
        note: args.note ? String(args.note).trim() : null,
      });
      const put = (text) => tasks.appendToSection(text, line, tasks.VOTES_SECTION);
      const saved = await writeFile(file, put(file.text), { rebase: put });
      const { counts, total } = tasks.parseVotes(saved);
      return {
        text: `Записал: ${winner}. Счёт после ${total}: процедурный ${counts['процедурный']} · свободный ${counts['свободный']} · ничьи ${counts['ничья']}.`,
        structured: { winner, counts, total, path: saved.path, rev: saved.rev },
      };
    },

    async tasks_learn(args = {}) {
      const file = await readFile(tasks.PREFS_PATH);
      const existing = tasks.parsePreferences(file);

      const note = String(args.note || '').trim();
      const question = String(args.question || '').trim();

      // Вопрос без ответа — это не запись, а проверка «я это уже спрашивал?».
      // Дешёвая: файл памяти всё равно поднят этим же вызовом.
      if (!note) {
        if (question) {
          const asked = tasks.knownPreference(existing, null, { question });
          // Найденное устаревшим отвечать нельзя: это ровно то значение,
          // которое он уже отменил. Спросить придётся заново — но зная, что
          // именно менялось, а не с чистого листа.
          const outdated = asked && asked.stale;
          return {
            text: asked
              ? (outdated
                ? `Спрашивал, но записанное устарело ${asked.stale.date}: было «${asked.note}»${asked.stale.replaced_by ? `, стало «${asked.stale.replaced_by}»` : ', замены не записано'}. Отвечать старым нельзя — спроси и запиши через replaces.`
                : `Это уже спрашивал: ${asked.date} записано «${asked.note}»${asked.evidence ? ` — ${asked.evidence}` : ''}. Второй раз не спрашивай.`)
              : 'Про это в памяти ничего нет — спроси один раз и запиши ответ вместе с вопросом.',
            structured: { asked: !!asked && !outdated, outdated: !!outdated, same_as: asked, question, path: tasks.PREFS_PATH },
          };
        }
        const live = tasks.activePreferences(existing);
        return {
          text: live.length
            ? `Про то, как он решает, записано ${live.length}: ${live.slice(-8).map((e) => e.note).join('; ')}.`
            : 'Пока ничего не записано про то, как он решает.',
          structured: { preferences: live, path: tasks.PREFS_PATH },
        };
      }

      const evidence = String(args.evidence || '').trim();
      if (!evidence) {
        throw new ToolError(
          'evidence_required',
          'Нужно, откуда это известно: его слова, дата разговора или ссылка на задачу. Без опоры это твоя догадка, а догадки такую память и обесценивают.',
        );
      }

      const asKind = tasks.PREFS_KINDS.includes(String(args.kind)) ? String(args.kind) : null;

      /**
       * Обновление записи. Отдельным аргументом, а не «второй записью поверх
       * первой», по двум причинам.
       *
       * Первая: узнать обновление по самому тексту нечем. Продал Solaris, купил
       * Duster — у старой и новой записи нет общих слов вовсе, похожесть 0.2,
       * и никакая проверка на дубль их не свяжет. Заменяемое приходится назвать.
       *
       * Вторая: обновление обязано быть намеренным. Будь оно побочным эффектом
       * обычной записи, опечатка в note («Дастор») тихо отменяла бы верный
       * факт — а память, которая портится сама, стоит дороже, чем не иметь её.
       *
       * Старое не стирается: на строке появляется отметка «устарело» с датой и
       * новым значением, и он читает историю глазами. Разрешено это для того,
       * что он говорил сам; наблюдением отменять его слово нельзя и здесь.
       */
      const replaces = String(args.replaces || '').trim();
      if (replaces) {
        const target = tasks.knownPreference(existing, replaces, { question: replaces });
        if (!target) {
          throw new ToolError(
            'nothing_to_replace',
            `В памяти нет записи, похожей на «${replaces}» — заменять нечего. Проверь формулировку через tasks_learn с одним question или запиши это обычной записью, без replaces.`,
          );
        }
        if (target.stale) {
          throw new ToolError(
            'already_replaced',
            `Эта запись уже помечена устаревшей ${target.stale.date}${target.stale.replaced_by ? `: заменена на «${target.stale.replaced_by}»` : ''}. Заменять надо ту, что действует сейчас, — назови в replaces её.`,
            { same_as: target },
          );
        }
        if (asKind === 'наблюдение' && tasks.PREFS_OWNER_KINDS.includes(target.kind)) {
          throw new ToolError(
            'observation_over_decision',
            `Это его ${target.kind} от ${target.date}: «${target.note}»${target.evidence ? ` — ${target.evidence}` : ''}. `
            + 'Своим наблюдением его слово не отменяется, даже через replaces. Если данные говорят другое — вынеси расхождение вопросом (tasks_standup с observe) и запиши то, что он ответит.',
            { same_as: target },
          );
        }
        // Вид, вопрос и синонимы наследуются: заменяют значение, а не смысл
        // записи. Потерянный вопрос отдельно опасен — по нему ловится повтор.
        // Синонимы теряются тише и потому хуже: «продал Дастер, купил Ларгус»
        // унесло бы «зовётся: тачка, авто», и на фразе «сколько ехать на тачке»
        // новый факт уже не поднялся бы. Свои синонимы, если переданы, важнее
        // старых — он назвал их к новому значению.
        const nextKind = asKind || target.kind;
        const block = tasks.preferenceBlock({
          date: today(), kind: nextKind, note, evidence,
          question: question || target.question || null,
          aliases: args.aliases || (target.aliases || []).join(', ') || null,
        });
        const put = (text) => {
          const marked = tasks.markPreferenceStale(text, target, { date: today(), replacedBy: note });
          if (!marked) return null;
          return tasks.appendToSection(marked, block, tasks.PREFS_SECTION);
        };
        const next = put(file.text);
        if (!next) {
          throw new ToolError(
            'replace_target_gone',
            `Строку «${target.note}» в файле памяти не нашёл — её успели поправить руками или из другой сессии. Ничего не записал: новое значение без погашенного старого оставило бы в памяти два разных ответа. Перечитай ${tasks.PREFS_PATH} и повтори.`,
          );
        }
        const saved = await writeFile(file, next, {
          rebase: (text) => {
            const again = put(text);
            if (!again) throw new ToolError('replace_target_gone', `Строку «${target.note}» в файле памяти успели изменить из другой сессии. Ничего не записал: перечитай ${tasks.PREFS_PATH} и повтори.`);
            return again;
          },
        });
        return {
          text: `Обновил: было «${target.note}» (${target.date}), стало «${note}». Старую строку пометил устаревшей — из файла она никуда не делась, вычёркивает он сам.`,
          structured: {
            created: true, updated: true, kind: nextKind, note, evidence,
            replaced: target, path: saved.path, rev: saved.rev,
            question: question || target.question || null,
          },
        };
      }

      const kind = asKind || 'предпочтение';
      const known = tasks.knownPreference(existing, note, { question: question || null });
      if (known) {
        // Записывают то, что уже отменено. Молча завести это второй строкой
        // хуже всего: в памяти окажутся два живых ответа на один вопрос, и
        // какой из них верный, не скажет никто.
        if (known.stale) {
          throw new ToolError(
            'outdated_value',
            `Это значение уже помечено устаревшим ${known.stale.date}: «${known.note}»${known.stale.replaced_by ? `, вместо него записано «${known.stale.replaced_by}»` : ''}. `
            + 'Если оно снова стало верным — запиши его через replaces с текстом действующей записи, чтобы старая погасла.',
            { same_as: known },
          );
        }
        /**
         * Разница в правах, ради которой «наблюдение» и заведено отдельным
         * видом. Его слово наблюдением не переписывается: вывод из данных
         * может быть верным и всё равно не иметь права отменять то, что он
         * решил сам. Отказ здесь, а не в правилах, потому что правило можно
         * не прочитать, а отказ инструмента — нет.
         */
        if (kind === 'наблюдение' && tasks.PREFS_OWNER_KINDS.includes(known.kind)) {
          throw new ToolError(
            'observation_over_decision',
            `Это его ${known.kind} от ${known.date}: «${known.note}»${known.evidence ? ` — ${known.evidence}` : ''}. `
            + 'Своим наблюдением его слово не переписывается. Если данные говорят другое — вынеси расхождение вопросом (tasks_standup с observe) и запиши то, что он ответит.',
            { same_as: known },
          );
        }
        // Свой вывод, подтвердившийся ещё раз, — не вторая запись, а та же с
        // отметкой: наблюдение имеет право уточняться само.
        if (kind === 'наблюдение' && known.kind === 'наблюдение') {
          const bumped = tasks.bumpPreferenceCounter(file.text, [known], { field: 'подтверждено', date: today() });
          const saved = await writeFile(file, bumped);
          const times = (known.confirmed?.count || 0) + 1;
          return {
            text: `Это уже наблюдалось ${known.date}: «${known.note}». Отметил подтверждение, теперь их ${times}. Второй записи не завожу.`,
            structured: { created: false, reason: 'confirmed', confirmed: times, same_as: known, path: saved.path, rev: saved.rev },
          };
        }
        /**
         * Факт, названный второй раз тем же значением, — это подтверждение.
         *
         * Без этой ветки цикл не закрывался: на планёрке факт выносится
         * вопросом «это ещё так?», он отвечает «да», и записать его ответ
         * нечем — тот же текст уходит в отказ по дублю, дата касания не
         * двигается, и на следующей планёрке тот же факт выносится снова.
         * Список, повторяющий одно и то же, перестают читать целиком.
         *
         * Только для фактов: у остальных видов срок считается от даты записи,
         * и подтверждать там нечего.
         *
         * Подтверждением считается ровно то же значение, а не похожее.
         * «Hyundai Солярис» против «Hyundai Solaris» — не подтверждение:
         * это либо опечатка, либо попытка поправить значение, и в обоих
         * случаях молчаливая отметка «подтверждено» была бы враньём. Такое
         * уходит в обычный отказ по дублю, где назван путь через replaces.
         */
        const sameValue = (a, b) => String(a || '').toLowerCase().replace(/ё/g, 'е')
          .replace(/[^\p{L}\p{N}]+/gu, ' ').trim()
          === String(b || '').toLowerCase().replace(/ё/g, 'е')
            .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
        if (kind === 'факт' && known.kind === 'факт' && sameValue(note, known.note)) {
          const bumped = tasks.bumpPreferenceCounter(file.text, [known], { field: 'подтверждено', date: today() });
          // Синонимы дописываются здесь же: это единственный путь добавить их
          // к живому факту, не штампуя на нём ложное «устарело».
          const withAliases = tasks.addPreferenceAliases(bumped, known, args.aliases);
          const saved = await writeFile(file, withAliases ? withAliases.text : bumped);
          const times = (known.confirmed?.count || 0) + 1;
          const said = withAliases ? ` Синонимы дописал: ${withAliases.added.join(', ')} — теперь запись поднимается и на них.` : '';
          return {
            text: `Этот факт уже записан ${known.date}: «${known.note}». Отметил, что он подтверждён сегодня — теперь подтверждений ${times}, и на проверку он выйдет не скоро. Второй записи не завожу.${said}`,
            structured: {
              created: false, reason: 'confirmed', confirmed: times, same_as: known,
              aliases_added: withAliases ? withAliases.added : [],
              path: saved.path, rev: saved.rev,
            },
          };
        }
        // Его слово поверх наблюдения агента — это не дубль: у записи другая
        // опора. Пишем новую строку, старое наблюдение не трогаем — вычёркивает
        // он сам, глазами.
        if (known.kind !== 'наблюдение') {
          // Отказ по дублю не должен съедать переданные синонимы: значение
          // остаётся прежним, меняется только то, какими словами его найдут.
          const withAliases = tasks.addPreferenceAliases(file.text, known, args.aliases);
          if (withAliases) {
            const saved = await writeFile(file, withAliases.text);
            return {
              text: `Уже записано ${known.date}: «${known.note}» — второй записи не завожу. Синонимы дописал: ${withAliases.added.join(', ')}, теперь запись поднимается и на них.`,
              structured: {
                created: false, reason: 'aliases_added', same_as: known,
                aliases_added: withAliases.added, path: saved.path, rev: saved.rev,
              },
            };
          }
          return {
            text: `Уже записано ${known.date}: «${known.note}». Второй раз не пишу.`
              + ' Если записанное перестало быть правдой — это не повтор, а замена: передай replaces с текстом старой записи, и она погаснет с датой.',
            structured: { created: false, reason: 'duplicate', same_as: known, path: tasks.PREFS_PATH },
          };
        }
      }

      const line = tasks.preferenceBlock({ date: today(), kind, note, evidence, question: question || null, aliases: args.aliases || null });
      const put = (text) => tasks.appendToSection(text, line, tasks.PREFS_SECTION);
      const saved = await writeFile(file, put(file.text), { rebase: put });

      const total = existing.length + 1;
      const crowded = total > tasks.PREFS_SOFT_LIMIT
        ? ` Записей уже ${total} — их стало больше, чем читают за раз; предложи ему вычистить устаревшее.`
        : '';
      const over = known && known.kind === 'наблюдение'
        ? ` Раньше это же было моим наблюдением (${known.date}: «${known.note}») — теперь есть его слово; старую строку он вычеркнет сам, я её не трогаю.`
        : '';
      return {
        text: `Запомнил: ${note}.${over}${crowded}`,
        structured: {
          created: true, path: saved.path, rev: saved.rev, kind, note, evidence, total,
          question: question || null,
          over_observation: over ? known : null,
        },
      };
    },

    async tasks_move(args = {}) {
      const { file, found, key } = await locateTask(args.project, args.hash);
      const target = String(args.to || '').toLowerCase().replace(/\.md$/i, '');
      if (!target) throw new ToolError('invalid_target', 'Нужно, куда переносить.');
      if (target === key) throw new ToolError('same_project', 'Задача уже в этом проекте.');

      const targetPath = target === 'archive'
        ? `archive/${today().slice(0, 7)}.md`
        : `projects/${target}.md`;

      const cut = tasks.cutTask(file.text, found.line);
      const targetFile = await readFile(targetPath);
      const nextTarget = target === 'archive'
        ? tasks.appendBlock(targetFile.text, cut.block)
        : tasks.appendToSection(targetFile.text, cut.block, '## Задачи');

      // Порядок важен: сначала кладём в приёмник, потом убираем из источника.
      // Обратный порядок при сбое между записями теряет задачу целиком.
      const savedTarget = await writeFile(targetFile, nextTarget);
      const savedSource = await writeFile(file, cut.text);

      const newHash = target === 'archive' ? null : tasks.taskHash(target, found.parsed.title);
      return {
        text: `Перенёс «${found.parsed.title}» из ${key} в ${target}.${newHash ? ` Новая ссылка: ${target}/${newHash}` : ''}`,
        structured: {
          from: savedSource.path,
          to: savedTarget.path,
          title: found.parsed.title,
          old_hash: args.hash,
          new_hash: newHash,
        },
      };
    },
  });

  // ── Агентский слой: дельта, связи, развитие контекстов ─────────────────

  function parseSince(value) {
    const raw = String(value || '').trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return Date.parse(`${raw}T00:00:00+03:00`); // задачник живёт по МСК
    const parsed = Date.parse(raw);
    if (Number.isFinite(parsed)) return parsed;
    throw new ToolError('invalid_since', `Не понимаю момент «${value}». Нужна дата YYYY-MM-DD или ISO-время.`);
  }

  Object.assign(tools, {
    /**
     * Разница с прошлого прохода.
     *
     * Дешевизна здесь — не оптимизация, а условие работоспособности: обход,
     * который стоит как чтение всего задачника, делают раз в день и потому
     * никогда. По индексу видно, какие файлы трогали, и читаются только они.
     */
    async tasks_delta(args = {}) {
      const index = await loadIndex();
      const state = await loadState();
      const sinceMs = args.since ? parseSince(args.since) : null;
      const seen = state.seen.files;
      const known = Object.keys(index.files);
      const firstPass = !sinceMs && !Object.keys(seen).length;

      const changedPaths = known.filter((path) => {
        const meta = index.files[path] || {};
        if (sinceMs) return (Number(meta.updatedAt) || 0) > sinceMs;
        const was = seen[path];
        return !was || Number(was.rev) !== (Number(meta.rev) || 0);
      });
      const gonePaths = Object.keys(seen).filter((path) => !index.files[path]);

      // Явный `since` — это разовый взгляд назад, а не проход: двигать метку
      // по нему нельзя, иначе следующий обычный вызов промолчит про то, что
      // на самом деле ещё не видели.
      const mark = args.mark !== false && !sinceMs;
      const toRead = firstPass ? known : changedPaths;
      const files = toRead.length ? await readAll({ paths: toRead, max: firstPass ? known.length : 40 }) : [];

      const diffs = [];
      const snapshots = {};
      for (const file of files) {
        const { diff, snapshot } = tasks.diffFile(seen[file.path] || null, file);
        snapshots[file.path] = snapshot;
        if (!firstPass) diffs.push(diff);
      }
      // Файл с выросшей ревизией, но пустым текстом батч не возвращает. Такой
      // файл всё равно называем и всё равно запоминаем: без отпечатка он будет
      // числиться изменившимся в каждом следующем проходе.
      for (const path of (firstPass ? known : changedPaths)) {
        if (snapshots[path]) continue;
        const meta = index.files[path] || {};
        snapshots[path] = { rev: Number(meta.rev) || 0, updatedAt: Number(meta.updatedAt) || 0, lines: 0 };
        if (firstPass) continue;
        diffs.push({
          path, status: 'changed', rev_from: seen[path] ? seen[path].rev : 0,
          rev_to: Number(meta.rev) || 0,
          appended: [], added_tasks: [], closed_tasks: [], changed_tasks: [], gone_tasks: [],
        });
      }

      if (mark) {
        const nextSeen = { ...seen, ...snapshots };
        for (const path of gonePaths) delete nextSeen[path];
        await writeState({ ...state, seen: { at: nowMs, files: nextSeen } });
      }

      if (firstPass) {
        return {
          text: `Первый проход: запомнил отпечаток задачника, файлов ${Object.keys(snapshots).length}. Со следующего вызова показываю только разницу.`,
          structured: { first_pass: true, files: Object.keys(snapshots).length, changed: [], gone: [], marked: mark },
        };
      }

      const counts = diffs.reduce((acc, d) => ({
        added: acc.added + d.added_tasks.length,
        closed: acc.closed + d.closed_tasks.length,
        changed: acc.changed + d.changed_tasks.length,
      }), { added: 0, closed: 0, changed: 0 });

      const parts = [];
      if (diffs.length) parts.push(`файлов изменилось: ${diffs.length}`);
      if (counts.added) parts.push(`новых задач: ${counts.added}`);
      if (counts.closed) parts.push(`закрыто: ${counts.closed}`);
      if (counts.changed) parts.push(`правок в задачах: ${counts.changed}`);
      if (gonePaths.length) parts.push(`файлов пропало: ${gonePaths.length}`);

      return {
        text: parts.length
          ? `С прошлого прохода — ${parts.join(', ')}. Где: ${diffs.map((d) => d.path).join(', ')}.`
          : 'С прошлого прохода в задачнике ничего не изменилось.',
        structured: {
          first_pass: false,
          since: sinceMs ? new Date(sinceMs).toISOString() : null,
          seen_at: state.seen.at || null,
          changed: diffs,
          gone: gonePaths,
          marked: mark,
        },
      };
    },

    /**
     * Явная связь между задачами. Цель проверяется до записи: ссылка на
     * несуществующий хэш выглядит как связь, а ведёт в пустоту — и обнаружится
     * это ровно тогда, когда по ней захотят пройти.
     */
    /**
     * Файл из разговора — в карточку.
     *
     * Порядок шагов выбран так, чтобы в хранилище не оставалось сирот: сперва
     * проверяется файл, потом находится карточка, и только затем идёт заливка.
     * Обратный порядок оставлял бы в репозитории вложения, на которые никто не
     * ссылается, а чистить их нечем.
     *
     * Строка в карточке — единственный результат, который переживёт разговор.
     * Ответ инструмента специально говорит об этом словами: файл, отданный
     * только в чат, через день не найдёт никто.
     */
    async tasks_attach(args = {}) {
      const caption = String(args.caption || '').replace(/\s+/g, ' ').trim();
      if (!caption) {
        throw new ToolError('caption_required', 'Вложению нужна подпись: что это за файл. Без неё строка в карточке станет бессмысленной в тот день, когда файл потеряется.');
      }

      const { kind, ext, maxBytes } = assets.classifyKind(args.filename);
      if (!kind) {
        throw new ToolError(
          'unsupported_file',
          ext
            ? `Файлы «.${ext}» не принимаются. Картинки: ${[...assets.IMAGE_EXTS].join(', ')}. Документы: ${[...assets.DOC_EXTS].join(', ')}.`
            : 'У файла нет расширения, а по нему определяется, картинка это или документ. Назови имя файла целиком: screenshot.jpg, счёт.pdf.',
        );
      }

      const base64 = String(args.content_base64 || '').replace(/\s+/g, '');
      if (!assets.isValidBase64(base64)) {
        throw new ToolError('invalid_content', 'Содержимое файла пришло не в base64. Нужен чистый base64, без префикса data: и без обрезки.');
      }
      const bytes = assets.base64Bytes(base64);
      if (bytes > maxBytes) {
        const kb = Math.round(bytes / 1024);
        const capKb = Math.round(maxBytes / 1024);
        throw new ToolError(
          'file_too_large',
          kind === 'image'
            ? `Картинка на ${kb} КБ, потолок — ${capKb} КБ. Сожми её там, где лежит файл: ширина около 1000, качество 60, цель — около 100 КБ. Здесь жать нечем.`
            : `Документ на ${kb} КБ, потолок — ${capKb} КБ. Документы не пережимаются: пришли файл меньшего объёма или раздели его.`,
          { kind, bytes, max_bytes: maxBytes },
        );
      }

      // Карточка ищется ДО заливки: не найдётся — в хранилище ничего не ляжет.
      const { file, found, key } = await locateTask(args.project, args.hash);

      const path = assets.assetPath({ filename: args.filename, caption, nowMs });
      const store = requireAssets();
      let res;
      try {
        res = await store.putFile({ path, base64, message: `вложение: ${path}` });
      } catch (err) {
        throw new ToolError('attach_upload_failed', `Не удалось положить файл в хранилище: ${store.scrub(err && err.message)}`);
      }
      if (!res.ok) {
        throw new ToolError('attach_upload_failed', `Файл не залит, в карточку ничего не записано. ${res.error}`, { status: res.status });
      }

      const line = assets.buildAttachLine({ path, caption });
      const saved = await writeFile(file, tasks.appendChild(file.text, found.line, line));
      return {
        text: `${key}/${String(args.hash).toLowerCase()} · ${found.parsed.title} → ${line}. Файл лежит в хранилище вложений, строка стоит в карточке — на доске он появится после ближайшей синхронизации. Отдать файл ещё и в чат можно, но карточка теперь и есть результат.`,
        structured: {
          path: saved.path,
          rev: saved.rev,
          task: `${key}/${String(args.hash).toLowerCase()}`,
          title: found.parsed.title,
          asset_path: path,
          kind,
          bytes,
          caption,
          line,
        },
      };
    },

    async tasks_link(args = {}) {
      const address = tasks.parseAddress(args.to);
      if (!address) throw new ToolError('invalid_ref', `Ссылка «${args.to}» не похожа на адрес с доски. Нужно «проект/хэш», например kinderly/8e3572.`);
      const { file, found, key } = await locateTask(args.project, args.hash);
      if (address.project === key && address.hash === String(args.hash).toLowerCase()) {
        throw new ToolError('self_link', 'Задача не ссылается сама на себя.');
      }

      const targetFile = await readFile(`projects/${address.project}.md`);
      const target = tasks.findTaskByHash(targetFile, address.hash);
      if (!target) {
        throw new ToolError('ref_not_found', `В ${targetFile.path} нет задачи ${address.project}/${address.hash}. Возьми адрес с доски или из tasks_list.`);
      }

      const current = tasks.parseTasks(file).find((t) => t.line - 1 === found.line);
      const already = (current ? current.children : []).some((child) => {
        const parsed = tasks.parseRefLine(child);
        return parsed && parsed.refs.some((r) => r.project === address.project && r.hash === address.hash);
      });
      if (already) {
        return {
          text: `${key}/${args.hash} уже ссылается на ${address.project}/${address.hash} — второй раз не пишу.`,
          structured: { from: `${key}/${args.hash}`, to: `${address.project}/${address.hash}`, already: true },
        };
      }

      const note = String(args.note || '').trim();
      const line = `см: ${address.project}/${address.hash}${note ? ` — ${note}` : ''}`;
      const saved = await writeFile(file, tasks.appendChild(file.text, found.line, line));
      return {
        text: `${key}/${args.hash} · ${found.parsed.title} → ${address.project}/${address.hash} · ${target.parsed.title}. Связь видна с обеих сторон.`,
        structured: {
          path: saved.path, rev: saved.rev, already: false,
          from: `${key}/${args.hash}`, from_title: found.parsed.title,
          to: `${address.project}/${address.hash}`, to_title: target.parsed.title,
          note: note || null,
        },
      };
    },

    /** Облачко с PWA-доски — тот же dual-write, что POST /talk на desktop board. */
    async board_entity_talk(args = {}) {
      const boardTalk = require('./board-talk');
      return boardTalk.entityTalk(args, { readFile, writeFile, nowMs, ToolError });
    },

    /** ✓ слота с PWA «Сегодня» — [x] в days/<date>.md. */
    async board_slot_done(args = {}) {
      const boardChecks = require('./board-checks');
      return boardChecks.slotDone(args, { readFile, writeFile, ToolError, today: today() });
    },

    /** ✓ привычки с PWA «Сегодня» — дата в habits.md (toggle). */
    async board_habit_done(args = {}) {
      const boardChecks = require('./board-checks');
      return boardChecks.habitDone(args, { readFile, writeFile, ToolError, today: today() });
    },

    /**
     * Обход «что видно только сверху».
     *
     * Потолок в три находки и память об отклонённом — не украшение, а условие
     * пользы. Без них проход приносит десяток «наблюдений», их перестают
     * читать, и вместе с ними перестают читать блок «Требует решения», ради
     * которого всё и делалось.
     */
    async tasks_review(args = {}) {
      const index = await loadIndex();
      const files = await readAll({ max: 80 });
      const state = await loadState();

      const all = tasks.reviewFindings(files, { nowMs, index });
      const { picked, skipped, held_back } = tasks.pickFindings(state, all, { nowMs, limit: args.limit });
      const post = args.post !== false;

      let nextState = state;
      const out = [];
      for (const finding of picked) {
        // Находка без своего проекта (повторяющаяся мысль журнала) ложится в
        // personal: это его собственная голова, а не проектная развилка.
        const project = finding.project || 'personal';
        let ref = null;
        if (post) {
          const posted = await tools.tasks_decision({
            project,
            // Находка про конкретную задачу вешается на неё: вторая задача про
            // то же самое разводит ответ по двум местам.
            hash: finding.hash || undefined,
            title: finding.title,
            questions: finding.questions,
            context: finding.context,
          });
          ref = `${project}/${posted.structured.hash}`;
        }
        nextState = tasks.rememberProposal(nextState, finding, { nowMs, ref });
        out.push({ key: finding.key, kind: finding.kind, title: finding.title, questions: finding.questions, context: finding.context, project, ref });
      }
      if (picked.length) await writeState(nextState);

      const tail = [];
      if (held_back) tail.push(`придержал ещё ${held_back} — потолок три за проход`);
      if (skipped.length) tail.push(`молчу про ${skipped.length}: уже предлагал`);

      return {
        text: out.length
          ? `Нашёл ${out.length}: ${out.map((f) => f.title).join('; ')}.${post ? ' Положил на доску.' : ''}${tail.length ? ` (${tail.join(', ')})` : ''}`
          : `Ничего нового не вижу.${tail.length ? ` (${tail.join(', ')})` : ''}`,
        structured: {
          findings: out,
          posted: post,
          held_back,
          skipped: skipped.map((f) => ({ key: f.key, title: f.title, status: f.cooldown.status, days_left: f.cooldown.days_left })),
        },
      };
    },

    /**
     * Ответ на предложение. Отклонённое молчит месяц — ровно так написано в
     * методичке про выделение контекста, и это же правило спасает остальные
     * находки: агент, который каждый день предлагает одно и то же, обесценивает
     * и то, что предлагает впервые.
     */
    async tasks_proposal(args = {}) {
      const state = await loadState();
      const entries = Object.entries(state.proposals);

      if (!args.key) {
        const list = entries.map(([key, entry]) => {
          const cooldown = tasks.proposalCooldown(entry, nowMs);
          return { key, title: entry.title, kind: entry.kind, status: entry.status, ref: entry.ref || null, days_left: cooldown.days_left };
        });
        return {
          text: list.length
            ? `Уже предлагал ${list.length}: ${list.map((p) => `${p.title} — ${p.status}${p.days_left ? `, молчу ещё ${p.days_left} дн.` : ''}`).join('; ')}.`
            : 'Пока ничего не предлагал.',
          structured: { proposals: list },
        };
      }

      const raw = String(args.answer || 'нет').trim().toLowerCase();
      const status = /^(да|yes|accept|accepted|принят)/.test(raw) ? 'accepted'
        : /^(позже|later|потом)/.test(raw) ? 'later'
          : 'declined';

      const next = tasks.answerProposal(state, String(args.key), { status, nowMs, note: args.note || null });
      if (!next) {
        throw new ToolError('proposal_not_found', `Такого предложения не помню: ${args.key}. Список — tasks_proposal без аргументов.`);
      }
      await writeState(next);

      const entry = next.proposals[String(args.key)];
      const cooldown = tasks.proposalCooldown(entry, nowMs);
      return {
        text: status === 'accepted'
          ? `Записал: «${entry.title}» принято.`
          : `Записал: «${entry.title}» — ${status === 'declined' ? 'нет' : 'позже'}. Не подниму ещё ${cooldown.days_left} дн.`,
        structured: { key: args.key, status, days_left: cooldown.days_left, title: entry.title },
      };
    },

    /**
     * Повестка планёрки.
     *
     * Отдельной сущностью, а не набором вызовов «на память»: утренний обход из
     * пяти инструментов держится ровно до первого раза, когда его собрали не в
     * том порядке. Здесь порядок и потолки заданы кодом, поэтому повестка
     * получается одинаковой каждое утро.
     *
     * Своего разбора задач тут нет. Что висит — считает tasks_list, время —
     * tasks_calendar, деньги — tasks_budget; их выводы берутся сводкой, а не
     * целиком, иначе повестка превращается в три отчёта подряд. Своё у планёрки
     * ровно две вещи: список принесённого заранее и поиск расхождений.
     */
    async tasks_standup(args = {}) {
      const today_ = today();
      const file = await readFile(tasks.STANDUP_PATH);
      const items = tasks.parseStandupItems(file);
      const observations = tasks.parseStandupObservations(file);

      // Положить вопрос на планёрку. Отвечаем коротко и ничего больше не
      // читаем: это реплика посреди разговора, а не начало утра.
      if (args.add) {
        const topic = String(args.add).trim();
        if (!topic) throw new ToolError('invalid_add', 'Нужно, о чём говорить на планёрке, — одной строкой.');
        const open = items.filter((i) => !i.done);
        const same = open.find((i) => tasks.questionSimilarity(topic, i.topic) >= tasks.DECISION_SIMILARITY);
        if (same) {
          return {
            text: `Это уже на планёрке с ${same.date}: «${same.topic}». Второй раз не пишу.`,
            structured: { created: false, reason: 'duplicate', same_as: same, path: tasks.STANDUP_PATH },
          };
        }
        const category = args.category && tasks.STANDUP_CATEGORIES.includes(args.category) ? args.category : 'общее';
        // Приоритет, решено 05.08: явный параметр побеждает всегда — над ним
        // ref к задаче не имеет силы. Без параметра приоритет пункту не
        // присваивается здесь: его на чтении даст ref или дефолт P2.
        let priority = null;
        if (args.priority !== undefined && args.priority !== null && args.priority !== '') {
          priority = String(args.priority).toUpperCase();
          if (!/^P[123]$/.test(priority)) throw new ToolError('invalid_priority', 'Приоритет — P1, P2 или P3.');
        }
        // Тема, решено 05.08: садится за ноутбук пачкой по одной зоне кода
        // или теме, а не по одному пункту. Свободный текст — задаёт он сам
        // или модель по смыслу разговора, список тем никем не ограничен.
        const session = args.session ? String(args.session).trim() : null;
        // Маркер пишем в файл только для «разработки»: «общее» — молчаливый
        // умолчательный случай (так читались все пункты до 05.08), и не стоит
        // захламлять строку меткой, которая ничего не меняет для читателя.
        const line = tasks.standupLine({
          date: today_, topic, note: args.note ? String(args.note).trim() : null,
          category: category === 'разработка' ? 'разработка' : null,
          priority,
          session,
        });
        const put = (text) => tasks.appendToSection(text, line, tasks.STANDUP_SECTION);
        const saved = await writeFile(file, put(file.text), { rebase: put });
        return {
          text: `На планёрку (${category}${priority ? `, ${priority}` : ''}${session ? `, тема «${session}»` : ''}): ${topic}. Сейчас в повестке ${open.length + 1}.`,
          structured: {
            created: true,
            path: saved.path,
            rev: saved.rev,
            topic,
            note: args.note || null,
            category,
            priority: priority || null,
            session: session || null,
            open: open.length + 1,
          },
        };
      }

      /**
       * Замеченное по смыслу. Кодом такое не проверяется — сравнить запись
       * журнала с содержимым дней может только модель, и она же может
       * ошибиться. Цена ошибки остаётся одним вопросом ровно при трёх
       * условиях, и все три стоят здесь, а не в правилах: наблюдение
       * формулируется вопросом с обеими сторонами, повтор блокируется той же
       * мерой схожести, что у развилок доски, а открытых наблюдений не больше
       * трёх зараз.
       */
      if (args.observe) {
        const question = String(args.observe).trim();
        if (!question) throw new ToolError('invalid_observe', 'Нужно, что именно заметил, — вопросом к нему.');
        const sides = (Array.isArray(args.sides) ? args.sides : [])
          .map((s) => String(s).trim())
          .filter(Boolean);
        if (sides.length < 2) {
          throw new ToolError(
            'sides_required',
            'Нужны обе стороны расхождения цитатами с указанием файла: что записано в одном месте и что в другом. Наблюдение без опоры он не проверит за секунду, и оно будет стоить дороже, чем сэкономит.',
          );
        }
        // Уже спрашивали — молчим. Отвеченное молчит навсегда: «это нормально»
        // на то и ответ, чтобы не возвращаться к теме другими словами.
        const same = tasks.knownObservation(observations, { question, sides });
        if (same) {
          return {
            text: same.answer
              ? `Про это уже спрашивал ${same.date}, он ответил: «${same.answer}». Второй раз не поднимаю.`
              : `Про это уже спрошено ${same.date}: «${same.question}». Ответа ещё нет — второй раз не спрашиваю.`,
            structured: { created: false, reason: same.answer ? 'answered' : 'duplicate', same_as: same, path: tasks.STANDUP_PATH },
          };
        }
        const open = observations.filter((o) => !o.done);
        if (open.length >= tasks.STANDUP_OBSERVE_CAP) {
          throw new ToolError(
            'too_many_observations',
            `Уже висит ${open.length} незакрытых наблюдения (потолок ${tasks.STANDUP_OBSERVE_CAP}): ${open.map((o) => `«${o.question}»`).join(', ')}. `
            + 'Новое не завожу: замеченное держится на том, что на него отвечают. Спроси про висящее и закрой через done с answer.',
          );
        }
        const block = tasks.observationBlock({ date: today_, question, sides });
        const put = (text) => tasks.appendToSection(text, block, tasks.STANDUP_OBSERVED_SECTION);
        const saved = await writeFile(file, put(file.text), { rebase: put });
        return {
          text: `Заметил и вынес вопросом: ${question}`,
          structured: { created: true, path: saved.path, rev: saved.rev, question, sides, open: open.length + 1 },
        };
      }

      // Сменить категорию пункта. Тот же матчер, что у done, но только по открытым
      // пунктам повестки — наблюдения сюда не входят. Пишется полем строки, не
      // через tasks_patch: иначе агент ломает дату/note/priority при «переписке».
      if (args.recategorize) {
        const needle = String(args.recategorize).trim().toLowerCase();
        if (!needle) throw new ToolError('invalid_recategorize', 'Нужна часть текста пункта, которому меняем категорию.');
        const category = args.category;
        if (!category || !tasks.STANDUP_CATEGORIES.includes(category)) {
          throw new ToolError(
            'invalid_category',
            `К recategorize нужна category: «разработка» или «общее». Получено: ${category == null ? 'ничего' : JSON.stringify(category)}.`,
          );
        }
        const matched = items
          .filter((i) => !i.done && `${i.topic} ${i.note || ''}`.toLowerCase().includes(needle))
          .map((i) => ({ line: i.line, title: i.topic, category: i.category }));
        if (!matched.length) {
          throw new ToolError(
            'standup_item_not_found',
            `В повестке нет открытого пункта со словами «${args.recategorize}». Список — tasks_standup без аргументов.`,
          );
        }
        if (matched.length > 1) {
          throw new ToolError(
            'ambiguous_standup_item',
            `Под «${args.recategorize}» подошло ${matched.length}: ${matched.map((i) => `«${i.title}»`).join(', ')}. Назови точнее.`,
          );
        }
        const hit = matched[0];
        if (hit.category === category) {
          return {
            text: `Уже в «${category}»: ${hit.title}.`,
            structured: {
              path: tasks.STANDUP_PATH, rev: file.rev, topic: hit.title,
              category, previous: hit.category, changed: false,
            },
          };
        }
        const saved = await writeFile(file, tasks.setStandupCategory(file.text, hit.line, category));
        return {
          text: `Перенёс в «${category}»: ${hit.title} (было «${hit.category}»).`,
          structured: {
            path: saved.path, rev: saved.rev, topic: hit.title,
            category, previous: hit.category, changed: true,
          },
        };
      }

      // Снять обсуждённое. Без этого пункт висит вечно, и через неделю повестку
      // перестают читать целиком — ровно так же, как переполненную доску.
      if (args.done) {
        const needle = String(args.done).trim().toLowerCase();
        if (!needle) throw new ToolError('invalid_done', 'Нужна часть текста пункта, который снимаем.');
        const matched = [
          ...items.filter((i) => !i.done && `${i.topic} ${i.note || ''}`.toLowerCase().includes(needle))
            .map((i) => ({ kind: 'пункт', line: i.line, title: i.topic })),
          ...observations.filter((o) => !o.done && `${o.question} ${o.sides.join(' ')}`.toLowerCase().includes(needle))
            .map((o) => ({ kind: 'наблюдение', line: o.line, title: o.question })),
        ];
        if (!matched.length) {
          throw new ToolError('standup_item_not_found', `В повестке нет пункта со словами «${args.done}». Список — tasks_standup без аргументов.`);
        }
        if (matched.length > 1) {
          throw new ToolError(
            'ambiguous_standup_item',
            `Под «${args.done}» подошло ${matched.length}: ${matched.map((i) => `«${i.title}»`).join(', ')}. Назови точнее, какой снимаем.`,
          );
        }
        const hit = matched[0];
        const said = args.answer ? String(args.answer).trim() : '';
        // Наблюдение без записанного ответа закрывать нельзя. Весь размен —
        // «спрошу, зато научусь» — держится на том, что ответ сохранён; без
        // него завтра будет задан тот же вопрос, и это уже придирка.
        if (hit.kind === 'наблюдение' && !said) {
          throw new ToolError(
            'answer_required',
            'Наблюдение закрывается только вместе с его ответом: передай answer его словами. Иначе завтра ты спросишь то же самое, и он перестанет отвечать на замеченное вовсе.',
          );
        }
        const nextText = hit.kind === 'наблюдение'
          ? tasks.answerObservation(file.text, hit.line, said)
          : tasks.markStandupDone(file.text, hit.line);
        const saved = await writeFile(file, nextText);
        const left = items.filter((i) => !i.done).length + observations.filter((o) => !o.done).length - 1;
        return {
          text: hit.kind === 'наблюдение'
            ? `Записал ответ и закрыл наблюдение: ${hit.title}. Больше про это не спрошу.${said ? ' Если это правило — запиши его через tasks_learn.' : ''}`
            : `Снял с планёрки: ${hit.title}.${left ? ` Осталось ${left}.` : ' Повестка пуста.'}`,
          structured: { path: saved.path, rev: saved.rev, kind: hit.kind, topic: hit.title, answer: said || null, left },
        };
      }

      /**
       * «Не трогать» — это спячка, а не удаление. Строка «открыто:» остаётся
       * под задачей: вопрос никуда не делся, его просто перестают задавать на
       * планёрке до названного дня. Снять вопрос совсем можно только ответом —
       * через tasks_resolve, и только с его слов.
       */
      if (args.sleep) {
        const needle = String(args.sleep).trim().toLowerCase();
        if (!needle) throw new ToolError('invalid_sleep', 'Нужна часть текста вопроса, который усыпляем.');
        const rawSleep = args.sleep_days === undefined || args.sleep_days === null
          ? tasks.QUESTION_SLEEP_DAYS
          : Number(args.sleep_days);
        if (!Number.isFinite(rawSleep) || rawSleep < 1) {
          throw new ToolError('invalid_sleep_days', 'Срок спячки — целое число дней от 1.');
        }
        const index = await loadIndex();
        const projectFiles = await readAll({ paths: projectPaths(index) });
        const all = tasks.collectOpenQuestions(projectFiles);
        const matched = all.filter((q) => q.question.toLowerCase().includes(needle));
        if (!matched.length) {
          throw new ToolError('question_not_found', `Открытого вопроса со словами «${args.sleep}» на доске нет. Список — tasks_standup без аргументов.`);
        }
        if (matched.length > 1) {
          throw new ToolError(
            'ambiguous_question',
            `Под «${args.sleep}» подошло ${matched.length}: ${matched.map((q) => `«${q.question}»`).join(', ')}. Назови точнее, какой усыпляем.`,
          );
        }
        const hit = matched[0];
        const days = Math.round(rawSleep);
        const until = tasks.shiftDate(today_, days);
        const state = await loadState();
        await writeState(tasks.sleepQuestion(state, hit, { until, nowMs }));
        return {
          text: `Не спрашиваю до ${until} (${days} дн.): «${hit.question}» — ${hit.ref}. Вопрос остался на доске, снимется только ответом через tasks_resolve.`,
          structured: { sleeping: true, key: hit.key, ref: hit.ref, question: hit.question, until, days },
        };
      }

      /**
       * Ревизия сделана. Отметка дописывается в КОНЕЦ каждого файла, чей хвост
       * сверяли, — и в этом вся механика: следующая планёрка прочитает только
       * то, что появилось ниже. Память прохода тут не участвует вовсе.
       *
       * Список файлов пересчитывается заново, а не берётся из прошлого ответа:
       * между показом блока и отметкой мог приехать новый обмен, и он тоже
       * прочитан — модель звала reviewed после чтения, а не до.
       *
       * Итог обязателен и пустым не принимается. Отметка без итога — это
       * галочка, а галочку ставят не читая; здесь же вся ценность шага в том,
       * что кто-то действительно прошёл хвост глазами.
       */
      if (args.reviewed !== undefined && args.reviewed !== null) {
        const summary = String(args.reviewed).trim();
        if (!summary) {
          throw new ToolError(
            'invalid_reviewed',
            'Нужен короткий итог ревизии: что нашёл в хвосте стенограммы неучтённого и куда завёл. Нашёл пусто — так и напиши. Пустая отметка гасит блок, ничего не сказав, — а тогда ревизии не было.',
          );
        }
        const round = await dayReviewRound(today_);
        const reasonDates = [...new Set((round.status.day_reasons || []).map((r) => r.date))];
        if (!round.status.days.length && !reasonDates.length) {
          return {
            text: `Отмечать нечего: несверенного хвоста в стенограммах и причин из закрытых дней за ${tasks.REVIEW_WINDOW_DAYS} дней нет.${
              round.status.today_missing ? ` Стенограммы за ${today_} нет вовсе — начни её писать, отметка ляжет в неё.` : ''}`,
            structured: { day_review: { date: today_, marked: [], summary, ...round.status } },
          };
        }
        const stamp = { date: tasks.moscowDate(nowMs), time: tasks.moscowTime(nowMs), summary };
        const marked = [];
        for (const day of round.status.days) {
          const file = await readFile(day.path);
          const markBlock = tasks.reviewMarkBlock(stamp);
          const put = (text) => tasks.appendReviewMark(text, stamp);
          const saved = await writeFile(file, put(file.text), {
            rebase: put,
            delta: tasks.isDeltaWritablePath(file.path) ? { mode: 'append', block: markBlock } : null,
          });
          marked.push({ path: saved.path, rev: saved.rev, date: day.date, kind: 'стенограмма' });
        }
        // Причины из «Закрыть день» сверены той же ревизией — отметка идёт в
        // сам день, тем же форматом строки (без заголовка «## ЧЧ:ММ», в дне
        // ему не место), чтобы при следующем заходе показать только новое.
        for (const date of reasonDates) {
          const file = await readFile(`days/${date}.md`);
          const put = (text) => tasks.appendDayReviewMark(text, stamp);
          const saved = await writeFile(file, put(file.text), { rebase: put });
          marked.push({ path: saved.path, rev: saved.rev, date, kind: 'причины дня' });
        }
        return {
          text: `Ревизия отмечена в ${marked.length === 1 ? 'файле' : `файлах (${marked.length})`}: ${
            marked.map((m) => `${m.path} (${m.kind})`).join(', ')}. Итог: ${summary}. На следующей планёрке прочитаешь только то, что появится ниже отметки.`,
          structured: {
            day_review: {
              date: today_, marked, summary, at: `${stamp.date} ${stamp.time}`,
            },
          },
        };
      }

      const rawDays = args.days === undefined || args.days === null ? 14 : Number(args.days);
      if (!Number.isFinite(rawDays) || rawDays < 1) throw new ToolError('invalid_days', 'Горизонт — целое число дней от 1.');
      const span = Math.min(Math.round(rawDays), 60);

      // Расхождения и зависшее считаются по своим файлам: их разбор живёт в
      // tasks.js и ни один соседний инструмент его не отдаёт.
      const index = await loadIndex();
      const dayPaths = Array.from({ length: span }, (_, i) => `days/${tasks.shiftDate(today_, i)}.md`);
      // Прошлые дни читаются только ради плана и факта, и только те, что уже
      // заведены: несуществующий день — это не «пусто», а лишний ключ в батче.
      const pastPaths = Array.from({ length: tasks.PLAN_FACT_WINDOW_DAYS }, (_, i) => `days/${tasks.shiftDate(today_, -(i + 1))}.md`)
        .filter((path) => index.files[path]);
      // Напоминания и деньги окна ревизии — только ради кандидатов на потерю:
      // названный час без слота проверяется по обоим, а сумма — по месяцу.
      // Оба ключа уезжают в тот же батч, лишнего round-trip не появляется.
      const reviewMonths = [...new Set([
        today_.slice(0, 7),
        tasks.shiftDate(today_, -(tasks.REVIEW_WINDOW_DAYS - 1)).slice(0, 7),
      ])];
      const wanted = [
        ...projectPaths(index), ...dayPaths, ...pastPaths, tasks.PREFS_PATH,
        tasks.REMINDERS_PATH, ...reviewMonths.map((month) => `money/${month}.md`),
      ];
      const files = await readAll({ paths: wanted, max: wanted.length });

      const divergences = tasks.findDivergences(files, { today: today_ });
      const stuck = tasks.stuckPromises(files, { today: today_ });

      /**
       * План против факта. Считается по файлам, но выносится вопросом, а не
       * утверждением: цифры говорят «не состоялось трижды», а почему — план
       * был неверный, дело сорвалось или просто забыли отметить — знает он.
       * Поэтому память отсюда не правится ни при каких условиях.
       *
       * Уже спрошенное молчит: тем же сравнением, что и остальные наблюдения,
       * иначе одно и то же расхождение всплывало бы каждое утро.
       */
      const planFact = tasks.planFactPatterns(files, { today: today_ })
        .filter((pattern) => !tasks.knownObservation(observations, {
          question: tasks.planFactQuestion(pattern),
          sides: tasks.planFactSides(pattern),
        }));

      // Память, которую пора пересмотреть. Только показать: удалять записанное
      // с его слов система не имеет права, и инструмента для этого нет вовсе.
      const staleMemory = tasks.stalePreferences(
        tasks.parsePreferences(files.find((f) => f.path === tasks.PREFS_PATH) || null),
        { today: today_ },
      );

      // Что висит — считает tasks_list, а не второй разбор задач здесь.
      const list = await tools.tasks_list({});
      const projectFiles = files.filter((f) => /^projects\//i.test(f.path));
      const openQuestions = tasks.collectOpenQuestions(projectFiles, { today: today_ });
      const todayDay = files.find((f) => f.path === `days/${today_}.md`);
      const decideGrouped = tasks.buildDecideGroups({
        blockedTasks: list.structured.blocked,
        openQuestions,
        today: today_,
        dayText: todayDay ? todayDay.text : '',
      });

      // Картина: только сводка.
      // экрана, и повестка после них перестаёт читаться за минуту.
      const calendar = await tools.tasks_calendar({ days: 7 });
      const budget = await tools.tasks_budget({});

      /**
       * Пять простых вопросов. Открытых на доске копится больше, чем
       * разбирается, и тонут они все вместе: список, который нельзя закрыть за
       * один заход, перестают открывать целиком. Отбираются те, на которые он
       * отвечает не вставая, и спрашиваются на КАЖДОЙ планёрке — утренней и
       * вечерней: цель у блока одна, чтобы открытых становилось меньше.
       *
       * Рекомендацию к каждому вопросу пишет модель в разговоре. Кодом её здесь
       * не собирают и не будут: «что я советую по этому вопросу» — это суждение,
       * а шаблон вместо суждения читается один раз и дальше пролистывается.
       */
      const simple = await simpleQuestionRound(
        tasks.collectOpenQuestions(files.filter((f) => /^projects\//i.test(f.path)), { today: today_ }),
        today_,
      );

      // Вчерашние деньги. Планёрка утренняя и закрывает вчерашний день —
      // значит и деньги вчерашнего дня уже полные, и это единственное место,
      // где вопрос «внесены?» имеет однозначный ответ.
      const money = await moneyDayNudge(tasks.shiftDate(today_, -1));

      // Ревизия. Идёт первым блоком и не режется потолком: повестка собрана
      // только из заведённого, и всё, что обсудили мимо задачника, видно ровно
      // здесь — пока хвост стенограммы не сверен и не отмечен.
      //
      // Кандидаты считаются отдельным шагом и под catch: подсказка не имеет
      // права уронить повестку. Не сосчиталась — блок выйдет без неё, и это
      // ровно то состояние, в котором ревизия жила до кандидатов.
      const round = await dayReviewRound(today_);
      let candidates = tasks.emptyReviewCandidates();
      try {
        const money_ = {};
        for (const file of files) {
          const month = /^money\/(\d{4}-\d{2})\.md$/i.exec(file.path);
          if (month) money_[month[1]] = file.text;
        }
        candidates = tasks.reviewCandidates(tasks.reviewTails(round.entries), {
          files,
          money: money_,
          openQuestions: tasks.collectOpenQuestions(files.filter((f) => /^projects\//i.test(f.path))),
          today: today_,
        });
      } catch { candidates = tasks.emptyReviewCandidates(); }
      const review = { ...round.status, candidates };

      const cap = tasks.STANDUP_GROUP_CAP;
      const decideShown = tasks.decideGroupsShown(decideGrouped, cap);
      const brought = items.filter((i) => !i.done);
      // Приоритет пункта, решено 05.08: явный маркер [P1]/[P3] побеждает,
      // иначе — приоритет задачи по ref (найден по тексту пункта), иначе P2.
      // Карта строится по уже прочитанным файлам проектов — второго чтения
      // ради этого не требуется.
      const priorityByRef = {};
      for (const f of files) {
        const projectKey = tasks.projectKeyForPath(f.path);
        if (!projectKey) continue;
        for (const t of tasks.parseTasks(f)) {
          priorityByRef[`${projectKey}/${tasks.taskHash(projectKey, t.title)}`] = t.priority || tasks.STANDUP_DEFAULT_PRIORITY;
        }
      }
      // Два блока вместо одного списка — его решение 05.08: садишься либо за
      // разработку доски и планёрки целиком, либо за остальную повестку,
      // не перескакивая. Категория пишется в строку самим add по предмету
      // разговора; старые пункты без маркера читаются как «общее». Внутри
      // каждого блока — по приоритету, решено 05.08, при равном приоритете
      // порядок как был (по дате добавления).
      const withEffectivePriority = (i) => ({ ...i, effective_priority: tasks.standupEffectivePriority(i, priorityByRef) });
      const broughtDev = tasks.sortStandupByPriority(brought.filter((i) => i.category === 'разработка'), priorityByRef)
        .map(withEffectivePriority);
      const broughtGeneral = tasks.sortStandupByPriority(brought.filter((i) => i.category !== 'разработка'), priorityByRef)
        .map(withEffectivePriority);
      const noticed = observations.filter((o) => !o.done);
      const groups = {
        brought_dev: { all: broughtDev, shown: broughtDev.slice(0, cap) },
        brought_general: { all: broughtGeneral, shown: broughtGeneral.slice(0, cap) },
        decide: { all: decideGrouped.all, shown: decideShown.all, groups: decideShown },
        // Расхождения потолком не режутся: каждое посчитано по файлам и
        // проверяется за секунду. Прятать доказанное «ради длины» значит
        // молчать про то, что и так молча копится.
        divergences: { all: divergences, shown: divergences },
        noticed: { all: noticed, shown: noticed.slice(0, tasks.STANDUP_OBSERVE_CAP) },
        plan_fact: { all: planFact, shown: planFact.slice(0, cap) },
        stuck: { all: stuck, shown: stuck.slice(0, cap) },
        stale_memory: { all: staleMemory, shown: staleMemory.slice(0, cap) },
      };
      const hidden = Object.fromEntries(
        Object.entries(groups).map(([name, g]) => [name, g.all.length - g.shown.length]),
      );
      const total = Object.values(groups).reduce((n, g) => n + g.all.length, 0);

      const more = (name) => (hidden[name] ? ` (и ещё ${hidden[name]} — не показываю, повестка должна читаться за минуту)` : '');
      const block = (title, name, render) => (groups[name].all.length
        ? `${title}${more(name)}:\n${groups[name].shown.map((x) => `- ${render(x)}`).join('\n')}`
        : null);

      // Пункты «принесённого» с одной темой (session, решено 05.08) рисуются
      // одним блоком под подзаголовком, а не вперемешку с остальными — он
      // садится за ноутбук пачкой по теме, а не по одному пункту.
      const fmtBrought = (i) => `${tasks.standupEffectivePriority(i, priorityByRef) !== tasks.STANDUP_DEFAULT_PRIORITY
        ? `${tasks.standupEffectivePriority(i, priorityByRef)} · ` : ''}${i.topic}${i.note ? ` — ${i.note}` : ''} (с ${i.date})`;
      const renderBrought = (title, name) => {
        const g = groups[name];
        if (!g.all.length) return null;
        const seen = new Set();
        const lines = [];
        for (const item of g.shown) {
          if (seen.has(item)) continue;
          if (item.session) {
            const cluster = g.shown.filter((x) => x.session === item.session);
            cluster.forEach((x) => seen.add(x));
            lines.push(`  тема «${item.session}»:`);
            for (const x of cluster) lines.push(`  - ${fmtBrought(x)}`);
          } else {
            seen.add(item);
            lines.push(`- ${fmtBrought(item)}`);
          }
        }
        return `${title}${more(name)}:\n${lines.join('\n')}`;
      };

      const picture = [
        `ближайшие 7 дней — свободных ${calendar.structured.free_days.length}`,
        calendar.structured.free_stretches.length
          ? `подряд ${calendar.structured.free_stretches.map((s) => `${s.from}…${s.to}`).join(', ')}`
          : null,
        `деньги ${budget.structured.month}: расходов ${budget.structured.spent} ₽, доходов ${budget.structured.income} ₽`,
        budget.structured.one_sided ? 'доходов за месяц в записях нет — вывод односторонний' : null,
      ].filter(Boolean).join('; ');

      const body = [
        // Ревизия стоит перед всем остальным намеренно: заводить найденное в
        // стенограмме надо ДО повестки, иначе повестка соберётся без него.
        tasks.dayReviewBlock(review),
        // Приоритет в тексте показываем только когда он не по умолчанию —
        // P2 у большинства пунктов и так молчаливый, метка для него была бы
        // шумом без новой информации. Пункты одной темы — общим блоком.
        renderBrought('Принесли на планёрку — разработка (доска, окно планёрки, коннектор, стенограмма)', 'brought_dev'),
        renderBrought('Принесли на планёрку — общее', 'brought_general'),
        tasks.renderDecideStandupBlock(decideGrouped, cap),
        simple.picked.length
          ? `Простые вопросы — задай все ${simple.picked.length}, к каждому дай свою рекомендацию, ответы разнеси через tasks_resolve в том же ходе:\n${
            simple.picked.map((q) => `- ${q.ref} · ${q.question} (${q.due ? `срок ${q.due}` : 'без срока'} · ${q.task})`).join('\n')}`
          : null,
        // Посчитанное и замеченное стоят разными блоками и названы по-разному.
        // Смешать их — значит выдать догадку за факт: после одного такого
        // случая перепроверять придётся и доказанное.
        block('Расхождения (посчитано по файлам)', 'divergences', (d) => d.what),
        block('Замечено — нужен твой ответ', 'noticed', (o) => `${o.question}\n${o.sides.map((s) => `  · ${s}`).join('\n')}`),
        // План и факт стоят отдельно от расхождений: там доказана ошибка в
        // данных, здесь — только счёт. Сколько дело заняло на самом деле, в
        // задачнике не записывает ничто, и делать вид, что мы это знаем, нельзя.
        block('План и факт (по закрытым дням; фактической длительности в задачнике нет) — спроси, не правь память', 'plan_fact',
          (p) => `${tasks.planFactQuestion(p)}\n${tasks.planFactSides(p).map((s) => `  · ${s}`).join('\n')}`),
        block('Зависшее', 'stuck', (s) => `${s.ref} · ${s.text} — ${s.days} дн.`),
        // У факта вопрос другой: не «это ещё нужно», а «это ещё так». Устаревший
        // факт не лежит мёртвым грузом, им отвечают, поэтому спрашивается он не
        // на выброс, а на подтверждение.
        block('Память на пересмотр — записи без применения и факты, которые давно не подтверждались; вычёркивает он сам', 'stale_memory',
          (p) => `${p.date} · ${p.kind} · ${p.note} (${p.age_days} дн.${p.reason === 'проверить' ? ', спроси — это ещё так?' : ''})`),
        money ? `Деньги за вчера:\n- ${money.reminder}` : null,
        `Картина: ${picture}.`,
      ].filter(Boolean).join('\n\n');

      const simpleTail = simple.picked.length
        ? ` Простых вопросов ${simple.picked.length} из ${simple.pool}${simple.sleeping.length ? `, в спячке ${simple.sleeping.length}` : ''}.`
        : '';
      const head = total
        ? `Планёрка ${today_}. Принесли ${groups.brought_dev.all.length + groups.brought_general.all.length} (разработка ${groups.brought_dev.all.length}, общее ${groups.brought_general.all.length}), требует решения ${groups.decide.all.length} (важное ${decideGrouped.hot.length}, быстро ${decideGrouped.quick.length}, остальное ${decideGrouped.rest.length}), расхождений ${groups.divergences.all.length}, замечено ${groups.noticed.all.length}, план и факт ${groups.plan_fact.all.length}, зависло ${groups.stuck.all.length}, память на пересмотр ${groups.stale_memory.all.length}.${simpleTail}`
        // Пустая повестка при несведённых деньгах или неразобранных простых
        // вопросах — не пустое утро: иначе шапка говорит «обсуждать нечего», а
        // строкой ниже стоят пять вопросов.
        : `Планёрка ${today_}. Обсуждать нечего: ничего не принесено, нерешённого нет, расхождений не нашёл.${
          money ? ' Кроме денег: за вчера в них ни одной операции.' : ''}${simpleTail}`;

      return {
        text: `${head}\n\n${body}`,
        structured: {
          date: today_,
          horizon_days: span,
          empty: total === 0 && !money && simple.picked.length === 0,
          money_yesterday: money ? money.status : null,
          day_review: review,
          simple_questions: simple.picked.map((q) => ({
            key: q.key, ref: q.ref, project: q.project, task: q.task, question: q.question, due: q.due,
          })),
          simple_questions_pool: simple.pool,
          simple_questions_round_reset: simple.round_reset,
          simple_questions_sleeping: simple.sleeping.map((q) => ({
            key: q.key, ref: q.ref, question: q.question, until: q.until,
          })),
          brought_dev: groups.brought_dev.shown,
          brought_general: groups.brought_general.shown,
          decide: groups.decide.shown,
          decide_groups: {
            hot: decideShown.hot,
            quick: decideShown.quick,
            rest: decideShown.rest,
            totals: {
              hot: decideGrouped.hot.length,
              quick: decideGrouped.quick.length,
              rest: decideGrouped.rest.length,
              all: decideGrouped.all.length,
            },
          },
          divergences: groups.divergences.shown,
          noticed: groups.noticed.shown,
          plan_fact: groups.plan_fact.shown,
          stuck: groups.stuck.shown,
          stale_memory: groups.stale_memory.shown,
          hidden,
          totals: Object.fromEntries(Object.entries(groups).map(([name, g]) => [name, g.all.length])),
          picture: {
            free_days: calendar.structured.free_days,
            free_stretches: calendar.structured.free_stretches,
            busiest_week: calendar.structured.busiest_week,
            month: budget.structured.month,
            spent: budget.structured.spent,
            income: budget.structured.income,
            one_sided: budget.structured.one_sided,
          },
          path: tasks.STANDUP_PATH,
        },
      };
    },

    /** Что делать прямо сейчас — под место, время и состояние, а не «всё». */
    async tasks_focus(args = {}) {
      const index = await loadIndex();
      const wanted = args.project
        ? [`projects/${String(args.project).toLowerCase().replace(/\.md$/i, '')}.md`]
        : projectPaths(index);
      const files = await readAll({ paths: wanted });

      const pool = files.flatMap((file) => {
        const project = tasks.projectKeyForPath(file.path);
        return tasks.parseTasks(file).map((task) => ({
          ...task,
          project,
          ref: `${project}/${tasks.taskHash(project, task.title)}`,
        }));
      });

      const moodRaw = String(args.mood || '').toLowerCase();
      const mood = /устал|не варит|низк|low|tired|туман/.test(moodRaw) ? 'low' : null;
      const place = args.place ? String(args.place).replace(/^#/, '').toLowerCase() : null;
      if (place && !tasks.PLACE_TAGS.has(place)) {
        throw new ToolError('invalid_place', `Место «${args.place}» не из словаря задачника: студия, дом, ноут, город.`);
      }

      // Занятость общего в этот час — факт рядом с подбором, а не фильтр.
      // Отсеивать по ней нельзя: пары «ресурс → запрещённое место» в коде нет
      // и быть не должно — студия у них рядом с тренировкой, то есть без
      // машины она достижима, а что-то другое нет. Это знание его, и приходит
      // оно из docs/preferences.md, куда его кладёт tasks_learn.
      let busy = [];
      if (args.at) {
        const date = args.date ? String(args.date).trim() : today();
        if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
          throw new ToolError('invalid_date', `Дата «${args.date}» не в формате ГГГГ-ММ-ДД.`);
        }
        const day = await readFile(`days/${date}.md`);
        try {
          busy = tasks.resourcesAt(tasks.parseSlots(day.text), args.at);
        } catch (e) {
          throw new ToolError('invalid_time', `Время «${args.at}» не в формате ЧЧ:ММ.`);
        }
      }

      const picked = tasks.pickFocus(pool, { place, minutes: args.minutes, mood, today: today(), limit: 3 });
      const situation = [place ? `#${place}` : null, args.minutes ? `${args.minutes} мин` : null, mood === 'low' ? 'голова не варит' : null]
        .filter(Boolean).join(', ');
      const busyNote = busy.length
        ? ` В ${args.at} занято: ${[...new Set(busy.map((r) => r.resource))].join(', ')} — ${[...new Set(busy.map((r) => `${r.title}${r.whose ? ` (${r.whose})` : ''}`))].join('; ')}. Отбор это не сузило: подходит ли дело под такое время, решает он.`
        : '';

      return {
        text: `${picked.length
          ? `${situation ? `${situation}: ` : ''}${picked.map((t) => `${t.ref} · ${t.title} (${t.reasons.join(', ') || 'ничего не мешает'})`).join('; ')}.`
          : `${situation ? `${situation}: ` : ''}под это ничего не подходит — либо всё занято местом, либо длиннее окна.`}${busyNote}`,
        structured: {
          situation: { place, minutes: args.minutes || null, mood, at: args.at || null, busy },
          picked: picked.map((t) => ({
            ref: t.ref, project: t.project, title: t.title, priority: t.priority,
            due: t.due, tags: t.tags, reasons: t.reasons, blocked: t.blocked, score: t.score,
          })),
        },
      };
    },

    /**
     * Напоминания. Единственное здесь, у чего есть своё хранилище: всё
     * остальное в этой тройке — вид на уже существующие записи.
     *
     * Дата обязательна, и это осознанный отказ, а не недоделка. «Напомни,
     * когда буду в студии» звучит выполнимо, но за местом человека в задачнике
     * не следит ничто: такое напоминание молча не сработало бы никогда, а
     * молчаливый отказ хуже честного. Привязка к месту в задачнике уже есть —
     * тег места на обычной задаче, который поднимает tasks_focus, когда он
     * скажет, где он; туда отказ и отправляет.
     */
    async tasks_remind(args = {}) {
      const file = await readFile(tasks.REMINDERS_PATH);
      const all = tasks.parseReminders(file);
      const today_ = today();

      // Снять. Идёт первым: «вспомнил про страховку» — это чаще снятие, чем
      // повод завести второе такое же.
      if (args.done) {
        const needle = String(args.done).trim().toLowerCase();
        if (!needle) throw new ToolError('invalid_done', 'Нужна часть текста напоминания, которое снимаем.');
        const matched = all.filter((r) => !r.done && r.text.toLowerCase().includes(needle));
        if (!matched.length) {
          // Повторное снятие — не ошибка и не повод трогать файл: он мог
          // сказать «убери» дважды или снять галочку руками в markdown.
          const already = all.filter((r) => r.done && r.text.toLowerCase().includes(needle));
          if (already.length) {
            return {
              text: `«${already[0].text}» уже снято (${already[0].date}). Файл не трогаю.`,
              structured: { removed: false, reason: 'already_done', reminder: already[0], path: tasks.REMINDERS_PATH },
            };
          }
          throw new ToolError('reminder_not_found', `Среди напоминаний нет ничего про «${args.done}».`);
        }
        if (matched.length > 1) {
          throw new ToolError(
            'ambiguous_reminder',
            `Под «${args.done}» подходит ${matched.length}: ${matched.map((r) => `${r.date} · ${r.text}`).join('; ')}. Уточни, какое снимаем.`,
            { matched },
          );
        }
        const hit = matched[0];
        const saved = await writeFile(file, tasks.markLineDone(file.text, hit.line));
        const left = all.filter((r) => !r.done).length - 1;
        return {
          text: `Снял: ${hit.text}. Активных напоминаний осталось ${left}.`,
          structured: { removed: true, path: saved.path, rev: saved.rev, reminder: hit, active: left },
        };
      }

      if (args.text) {
        const text = String(args.text).trim();
        if (!text) throw new ToolError('invalid_text', 'Нужен текст напоминания.');
        const date = args.date ? String(args.date).trim() : null;
        if (!date) {
          throw new ToolError(
            'date_required',
            'Напоминанию нужен день: всплывает оно по дате и больше ни по чему. За местом и условиями — «когда буду в студии», «как освободится Даня» — в задачнике не следит ничто, и такое напоминание не сработало бы никогда. Если привязка к месту, а не ко дню, это обычная задача с тегом места (студия, дом, ноут, город) через tasks_capture: её поднимет tasks_focus, когда он скажет, где он. Если день всё-таки назван — передай его.',
          );
        }
        if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
          throw new ToolError('invalid_date', `Дата «${args.date}» не в формате YYYY-MM-DD.`);
        }
        let time = args.time ? String(args.time).trim() : null;
        if (time && !/^\d{1,2}:\d{2}$/.test(time)) {
          throw new ToolError('invalid_time', `Время «${args.time}» не в формате ЧЧ:ММ.`);
        }
        // Час приводится к тому же виду, в каком ляжет в файл: «в 9:00» в
        // ответе и «09:00» в строке — это уже два разных напоминания на вид.
        if (time) {
          try { time = tasks.padTime(time); } catch { throw new ToolError('invalid_time', `Время «${args.time}» не в формате ЧЧ:ММ.`); }
        }
        // Шапка объясняет формат тому, кто откроет файл руками, — поэтому она
        // пишется вместе с первой строкой, а не когда-нибудь потом.
        const line = tasks.reminderLine({ date, time, text });
        const put = (current) => tasks.appendToSection(
          current.trim() ? current : tasks.REMINDERS_HEADER,
          line,
          tasks.REMINDERS_SECTION,
        );
        const saved = await writeFile(file, put(file.text), { rebase: put });
        const active = tasks.activeReminders([...all, { done: false, date, time, text, line: -1 }], { today: today_ });
        const late = date < today_;
        return {
          text: `Напомню ${date}${time ? ` в ${time}` : ''}: ${text}.${late ? ' День уже прошёл — покажу сразу.' : ''} Активных: ${active.length}.`,
          structured: { created: true, path: saved.path, rev: saved.rev, date, time: time || null, text, active: active.length },
        };
      }

      if (args.date || args.time) {
        throw new ToolError('invalid_text', 'День назван, а о чём вспомнить — нет. Передай text.');
      }

      const active = tasks.activeReminders(all, { today: today_ });
      const overdue = active.filter((r) => r.overdue);
      const now = active.filter((r) => r.today);
      const ahead = active.filter((r) => !r.overdue && !r.today);
      const show = (r) => `${r.date}${r.time ? ` ${r.time}` : ''} · ${r.text}`;
      return {
        text: active.length
          ? [
            overdue.length ? `Просрочено (${overdue.length}): ${overdue.map(show).join('; ')}` : null,
            now.length ? `Сегодня: ${now.map(show).join('; ')}` : null,
            ahead.length ? `Впереди: ${ahead.map(show).join('; ')}` : null,
          ].filter(Boolean).join('. ')
          : 'Активных напоминаний нет.',
        structured: {
          path: tasks.REMINDERS_PATH,
          active,
          overdue,
          today: now,
          ahead,
          done: all.filter((r) => r.done).length,
        },
      };
    },

    /**
     * Быстрые дела. Своего хранилища нет намеренно: заведи их отдельной
     * сущностью — и одна задача окажется в двух местах, а закрытая в одном
     * останется открытой в другом. Это выборка по тем же задачам проектов, и
     * отбор идёт тем же движком, что у tasks_focus, а не третьим разбором.
     */
    async tasks_quick(args = {}) {
      const raw = args.minutes === undefined || args.minutes === null ? 15 : Number(args.minutes);
      if (!Number.isFinite(raw) || raw < 1) throw new ToolError('invalid_minutes', 'Потолок — целое число минут от 1.');
      const minutes = Math.round(raw);

      const index = await loadIndex();
      const files = await readAll({ paths: projectPaths(index) });
      const pool = files.flatMap((file) => {
        const project = tasks.projectKeyForPath(file.path);
        return tasks.parseTasks(file).map((task) => ({
          ...task,
          project,
          ref: `${project}/${tasks.taskHash(project, task.title)}`,
        }));
      });

      // pickFocus пропускает и задачи без тега времени — им окно не мешает.
      // Здесь наоборот: без тега задача в «быстрые дела» не попадает, потому
      // что никто не знает, быстрая она или на полдня.
      const open = pool.filter((task) => !task.done && !task.waiting);
      const picked = tasks.pickFocus(pool, { minutes, today: today(), limit: pool.length })
        .filter((task) => tasks.taskMinutes(task));
      const untagged = open.filter((task) => !tasks.taskMinutes(task)).length;

      // Пустой список тут — почти всегда норма, и сказать об этом обязательно:
      // иначе он прочитает «дел нет» там, где написано «теги не расставлены».
      const why = `Задач без тега времени — ${untagged} из ${open.length} открытых: сюда они не попадают, тег ставится руками.`;
      return {
        text: picked.length
          ? `Короче ${minutes} мин: ${picked.map((t) => `${t.ref} · ${t.title}`).join('; ')}. ${why}`
          : `Ничего короче ${minutes} мин не нашлось. ${why}`,
        structured: {
          minutes,
          picked: picked.map((t) => ({
            ref: t.ref, project: t.project, title: t.title, priority: t.priority,
            due: t.due, tags: t.tags, minutes: tasks.taskMinutes(t), reasons: t.reasons, blocked: t.blocked,
          })),
          without_time_tag: untagged,
          open_total: open.length,
        },
      };
    },

    /**
     * Быстро заказать. Решено 03.08, реализовано 05.08: покупки — не то же
     * самое, что «быстрые дела» (tasks_quick). У покупки есть площадка и
     * цена, а забытый заказ стоит не десяти минут, а недели ожидания. Своей
     * сущности всё равно нет — это те же задачи проектов с тегом «заказ»,
     * закрываются они здесь же, потому что закрытие покупки без записи её
     * стоимости оставляет ту самую дыру в деньгах, ради которой блок и
     * заводился.
     */
    async tasks_orders(args = {}) {
      const index = await loadIndex();
      const files = await readAll({ paths: projectPaths(index) });
      const pool = files.flatMap((file) => {
        const project = tasks.projectKeyForPath(file.path);
        return tasks.parseTasks(file).map((task) => ({
          ...task,
          project,
          ref: `${project}/${tasks.taskHash(project, task.title)}`,
        }));
      });
      const open = pool.filter((task) => !task.done && !task.waiting && task.tags.includes('заказ'));

      // Закрыть покупку: галочка в проекте плюс расход в money — одним
      // вызовом, чтобы решение «закрыл заказ — записал трату» выполнялось
      // само, а не держалось на памяти о втором шаге.
      if (args.done) {
        const needle = String(args.done).trim().toLowerCase();
        if (!needle) throw new ToolError('invalid_done', 'Нужна часть названия покупки, которую закрываем.');
        const matched = open.filter((t) => t.title.toLowerCase().includes(needle));
        if (!matched.length) {
          throw new ToolError('order_not_found', `Среди «Быстро заказать» нет ничего со словами «${args.done}». Список — tasks_orders без аргументов.`);
        }
        if (matched.length > 1) {
          throw new ToolError(
            'ambiguous_order',
            `Под «${args.done}» подошло ${matched.length}: ${matched.map((t) => `${t.ref} · ${t.title}`).join(', ')}. Назови точнее.`,
          );
        }
        const amount = Number(args.amount);
        if (!Number.isFinite(amount) || amount <= 0) {
          throw new ToolError('invalid_amount', 'Нужна сумма покупки — положительное число. Без неё это была бы закрытая задача и молчаливая дыра в деньгах, ровно то, из-за чего блок заводился.');
        }
        const contour = String(args.contour || '').trim();
        if (!contour) throw new ToolError('contour_required', 'Нужен контур траты — без него она не попадёт в разбивку на доске.');
        const category = String(args.category || 'заказы').trim();

        const hit = matched[0];
        const projFile = await readFile(`projects/${hit.project}.md`);
        const found = tasks.findTaskByHash(projFile, tasks.taskHash(hit.project, hit.title));
        if (!found) throw new ToolError('task_not_found', `Задача «${hit.title}» пропала из ${projFile.path} между чтением и записью — перечитай tasks_orders.`);
        const lines = projFile.text.split('\n');
        const patched = tasks.applyTaskPatch(lines[found.line], { state: 'done' });
        const nextTaskText = [...lines.slice(0, found.line), patched, ...lines.slice(found.line + 1)].join('\n');
        const savedTask = await writeFile(projFile, nextTaskText);

        const date = today();
        const month = date.slice(0, 7);
        const moneyFile = await readFile(`money/${month}.md`);
        const moneyLineText = tasks.moneyLine({
          date, amount: -Math.abs(amount), income: false, category, contour, comment: hit.title,
        });
        const putMoney = (text) => tasks.prependToSection(text, moneyLineText, '## Операции');
        const savedMoney = await writeFile(moneyFile, putMoney(moneyFile.text), { rebase: putMoney });

        return {
          text: `Куплено: ${hit.title} — ${amount} ₽ (${contour}/${category}). Задача закрыта, расход записан.`,
          structured: {
            ref: hit.ref, title: hit.title, amount, contour, category,
            task_path: savedTask.path, task_rev: savedTask.rev,
            money_path: savedMoney.path, money_rev: savedMoney.rev,
          },
        };
      }

      // Площадка и цена — необязательные вложенные строки задачи вида
      // «площадка: Озон» / «цена: ~500». Не назвал — просто не показываем,
      // придумывать за него нельзя.
      const readField = (task, label) => {
        const line = (task.children || []).find((c) => new RegExp(`^${label}:`, 'i').test(c.trim()));
        return line ? line.trim().replace(new RegExp(`^${label}:\\s*`, 'i'), '') : null;
      };
      const rows = open.map((t) => ({
        ref: t.ref, project: t.project, title: t.title,
        place: readField(t, 'площадка'), price: readField(t, 'цена'),
        due: t.due, overdue: t.overdue,
      }));

      return {
        text: rows.length
          ? `Быстро заказать (${rows.length}): ${rows.map((r) => `${r.ref} · ${r.title}${r.place ? ` — ${r.place}` : ''}${r.price ? ` (${r.price})` : ''}`).join('; ')}`
          : 'Заказывать нечего — под тегом #заказ ничего не открыто.',
        structured: { open: rows },
      };
    },

    /**
     * Идеи. Раздел `## Идеи` в someday.md существовал пустым — своего входа у
     * него не было. Отдельный файл заводить не за чем: место есть, не хватало
     * только способа туда класть и оттуда доставать.
     */
    async tasks_idea(args = {}) {
      const file = await readFile(tasks.SOMEDAY_PATH);
      const ideas = tasks.parseIdeas(file);
      const today_ = today();

      function findIdea(needleRaw, what) {
        const needle = String(needleRaw || '').trim().toLowerCase();
        if (!needle) throw new ToolError('idea_required', `Нужно, к какой идее относится ${what}, — часть её текста.`);
        const matched = ideas.filter((i) => i.text.toLowerCase().includes(needle));
        if (!matched.length) throw new ToolError('idea_not_found', `Среди идей нет ничего про «${needleRaw}».`);
        if (matched.length > 1) {
          throw new ToolError(
            'ambiguous_idea',
            `Под «${needleRaw}» подходит ${matched.length}: ${matched.map((i) => i.text).join('; ')}. Уточни, о какой речь.`,
            { matched },
          );
        }
        return matched[0];
      }

      // Превратить идею в задачу проекта. Накопленное переезжает вместе с ней:
      // без этого «развивал-развивал» заканчивается голым заголовком.
      if (args.to_project) {
        const hit = findIdea(args.idea, 'превращение');
        const project = String(args.to_project).toLowerCase().replace(/\.md$/i, '');
        const targetPath = `projects/${project}.md`;
        const index = await loadIndex();
        if (!projectPaths(index).includes(targetPath)) {
          throw new ToolError(
            'project_not_found',
            `Проекта «${project}» нет. Есть: ${projectPaths(index).map((p) => tasks.projectKeyForPath(p)).join(', ')}.`,
          );
        }
        const priority = args.priority ? String(args.priority).toUpperCase() : 'P2';
        if (!/^P[123]$/.test(priority)) throw new ToolError('invalid_priority', 'Приоритет — P1, P2 или P3.');

        const taskLine = `- [ ] ${priority} ${hit.text} ^${today_}`;
        const block = [taskLine, ...hit.notes.map((n) => `  - ${n}`)].join('\n');
        const cut = tasks.cutTask(file.text, hit.line);

        if (targetPath === file.path) {
          await writeFile(file, tasks.appendToSection(cut.text, block, '## Задачи'));
        } else {
          // Сначала завести задачу, потом убрать идею: оборвись это посередине,
          // запись задвоится, а не пропадёт.
          const target = await readFile(targetPath);
          await writeFile(target, tasks.appendToSection(target.text, block, '## Задачи'));
          await writeFile(file, cut.text);
        }

        const title = tasks.taskTitle(taskLine);
        const ref = `${project}/${tasks.taskHash(project, title)}`;
        return {
          text: `Идея стала задачей ${project}: ${priority} ${title}${hit.notes.length ? `, накопленное перенёс (${hit.notes.length})` : ''}. Ссылка: ${ref}`,
          structured: {
            promoted: true, ref, project, title, priority,
            notes_moved: hit.notes.length, from: tasks.SOMEDAY_PATH, path: targetPath,
          },
        };
      }

      if (args.note) {
        const note = String(args.note).trim();
        if (!note) throw new ToolError('invalid_note', 'Нужен текст мысли.');
        const hit = findIdea(args.idea, 'мысль');
        const saved = await writeFile(file, tasks.appendChild(file.text, hit.line, note));
        return {
          text: `К идее «${hit.text}» дописал: ${note}. Накоплено мыслей: ${hit.notes.length + 1}.`,
          structured: { added: true, path: saved.path, rev: saved.rev, idea: hit.text, note, notes: hit.notes.length + 1 },
        };
      }

      if (args.text) {
        const text = String(args.text).trim();
        if (!text) throw new ToolError('invalid_text', 'Нужен текст идеи.');
        const line = tasks.ideaLine({ date: today_, text });
        const put = (text) => tasks.appendToSection(text, line, tasks.IDEAS_SECTION);
        const saved = await writeFile(file, put(file.text), { rebase: put });
        return {
          text: `Записал в идеи: ${text}. Всего идей: ${ideas.length + 1}.`,
          structured: { created: true, path: saved.path, rev: saved.rev, text, total: ideas.length + 1 },
        };
      }

      if (args.idea) {
        const hit = findIdea(args.idea, 'показ');
        return {
          text: `${hit.date} · ${hit.text}${hit.notes.length ? `. Накоплено: ${hit.notes.join('; ')}` : '. Мыслей под ней пока нет.'}`,
          structured: { idea: hit, path: tasks.SOMEDAY_PATH },
        };
      }

      return {
        text: ideas.length
          ? `Идей ${ideas.length}: ${ideas.map((i) => `${i.text}${i.notes.length ? ` (мыслей ${i.notes.length})` : ''}`).join('; ')}.`
          : 'В идеях пусто.',
        structured: { ideas, path: tasks.SOMEDAY_PATH },
      };
    },
  });

  /**
   * Где напоминать про стенограмму и где ставить transcript_pending.
   *
   * Не везде: приписка в каждом ответе перестаёт читаться на второй день. Сюда
   * попали вызовы, каждый из которых означает содержательный обмен — он что-то
   * сказал, и это осело в задачнике. Механические (`tasks_read`, `tasks_list`,
   * `tasks_delta`, отметка привычки, перестановка слота) остались снаружи:
   * они бывают и без разговора.
   *
   * PENDING_WRITE_TOOLS — мутации, после которых без checkpoint дыра в стенограмме
   * (heys/49f059). tasks_standup без аргументов — чтение повестки, pending не ставим.
   */
  const TRANSCRIPT_NUDGE_TOOLS = [
    'tasks_context',
    'tasks_capture',
    'tasks_append',
    'tasks_decision',
    'tasks_resolve',
    'tasks_learn',
    'tasks_close_day',
    'tasks_standup',
  ];

  const PENDING_WRITE_TOOLS = new Set([
    'tasks_capture',
    'tasks_update',
    'tasks_append',
    'tasks_decision',
    'tasks_resolve',
    'tasks_learn',
    'tasks_close_day',
    'tasks_patch',
    'tasks_slot',
    'tasks_slot_done',
    'tasks_money',
    'tasks_remind',
    'tasks_idea',
  ]);

  let transcriptNudged = false;

  async function markPending(toolName) {
    try {
      const state = await loadState();
      await writeState(tasks.markTranscriptPending(state, {
        tool: toolName, day: today(), nowMs,
      }));
    } catch {
      // pending не имеет права ломать запись
    }
  }

  async function transcriptNote() {
    if (transcriptNudged) return null;
    try {
      const index = await loadIndex();
      const status = tasks.transcriptStatus(index, { date: today(), nowMs });
      // Пустая/отставшая стенограмма важнее флага pending: это тот же пробел,
      // только грубее, и старые тесты/привычка читают именно эту формулировку.
      const ageReminder = tasks.transcriptReminder(status);
      if (ageReminder) {
        transcriptNudged = true;
        return ageReminder;
      }
      const state = await loadState();
      if (state.transcript_pending) {
        transcriptNudged = true;
        const tool = state.transcript_pending.tool || 'запись';
        return `Стенограмма не закрыта после «${tool}» — вызови tasks_checkpoint.`;
      }
      return null;
    } catch {
      return null;
    }
  }

  function standupMutates(args = {}) {
    return Boolean(
      args.add || args.observe || args.done || args.recategorize
      || args.sleep || args.reviewed,
    );
  }

  for (const name of Object.keys(tools)) {
    if (!PENDING_WRITE_TOOLS.has(name) && name !== 'tasks_standup') continue;
    if (name === 'tasks_checkpoint') continue;
    const inner = tools[name];
    if (typeof inner !== 'function') continue;
    tools[name] = async (args = {}) => {
      if (name === 'tasks_standup' && !standupMutates(args)) return inner(args);
      // append в саму стенограмму — это и есть запись дословного слоя
      if (name === 'tasks_append' && /^transcript\//i.test(String(args.path || ''))) {
        const result = await inner(args);
        try {
          const state = await loadState();
          if (state.transcript_pending) await writeState(tasks.clearTranscriptPending(state));
        } catch { /* ignore */ }
        return result;
      }
      const result = await inner(args);
      await markPending(name);
      return {
        ...result,
        structured: { ...(result.structured || {}), transcript_pending: true },
      };
    };
  }

  for (const name of TRANSCRIPT_NUDGE_TOOLS) {
    const inner = tools[name];
    if (typeof inner !== 'function') continue;
    tools[name] = async (args = {}) => {
      const result = await inner(args);
      const reminder = await transcriptNote();
      if (!reminder) return result;
      return {
        ...result,
        text: typeof result.text === 'string' ? `${result.text}\n\n${reminder}` : result.text,
        structured: {
          ...(result.structured || {}),
          transcript_reminder: reminder,
        },
      };
    };
  }

  /**
   * Прогрев стенограммы за сегодня: зовётся перед записью в дневник, чтобы
   * чтение файла ехало параллельно самой записи, а не после неё.
   */
  function prefetchTranscript(date) {
    try {
      prefetchAppend(tasks.transcriptPath(checkpointDay(date)));
    } catch {
      // Прогрев необязателен: неверную дату отвергнет сам checkpoint.
    }
  }

  return {
    tools,
    prefetchTranscript,
    schemas: [...TASKS_TOOL_SCHEMAS, ...TASKS_WRITE_SCHEMAS, ...TASKS_BOARD_SCHEMAS, ...TASKS_AGENT_SCHEMAS],
  };
}

module.exports = {
  createTasksTools, TASKS_TOOL_SCHEMAS, TASKS_WRITE_SCHEMAS, TASKS_BOARD_SCHEMAS, TASKS_AGENT_SCHEMAS,
};
